module TopModule(clk, resetn, byteena, d, q);

    reg [15:0] q[16];
    reg [1:0] byteena_value;

    // Initialize all q values to 0
    initial begin
        for (int i = 0; i < 16; i++) begin
            q[i] = 0;
        end
    end

    always_comb begin
        byteena_value = byteena[1] + 2 * byteena[0];
    end

    // Assign byteena value to q[7:0]
    always_comb begin
        q[7] = d[7];
        q[8] = d[8];
        q[9] = d[9];
        q[10] = d[10];
        q[11] = d[11];
        q[12] = d[12];
        q[13] = d[13];
        q[14] = d[14];
        q[15] = d[15];
    end

    // Assign byteena value to q[15:8]
    always_comb begin
        q[15] = d[15];
        q[14] = d[14];
        q[13] = d[13];
        q[12] = d[12];
        q[11] = d[11];
        q[10] = d[10];
        q[9] = d[9];
        q[8] = d[8];
    end

    // Write q to flip-flops
    always @(posedge clk) begin
        if (!resetn) begin
            for (int i = 0; i < 16; i++) begin
                q[i] = 0;
            end
        end else begin
            // Write byteena value to first byte of q
            for (int i = 7; i >= 0; i--) begin
                if (byteena_value == 2) begin
                    q[i] = q[i+1];
                end else if (byteena_value == 1) begin
                    q[i] = q[i+1];
                end else begin
                    q[i] = d[15];
                end
            end

            // Write byteena value to second byte of q
            for (int i = 0; i < 8; i++) begin
                if (byteena_value == 2) begin
                    q[i] = q[i+8];
                end else if (byteena_value == 1) begin
                    q[i] = q[i+8];
                end else begin
                    q[i] = d[0];
                end
            end
        end
    end

    // Output q to output port
    output [15:0] reg out_q;
    assign out_q = q;

endmodule

