            qreg[0] <= 0;
            for (int i = 1; i <= 15; i++) qreg[i] <= 0;
        end
        else begin
            for (int i = 0; i <= 15; i++) begin
                if (byteena[i] == 2'b01) begin
                    qreg[i + 1] <= d[7:0];
                end else if (byteena[i] == 2'b10) begin
                    qreg[i + 1] <= d[15:8];
                end else begin
                    qreg[i + 1] <= d[i];
                end
            end
        end
    end

