module TopModule(
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output [3:0] out
);

// One-hot state encoding
assign next_state = state;
assign out = state == 4'b0001 ? 'z : state[1:0];

// State transition logic
always_comb begin
    case (state)
        4'b0001: out = 'z;
        4'b0010: out = 'z;
        4'b0100: out = 'z;
        4'b1000: out = 'z;
        default: out = state[1:0];
    endcase
end

// State transition table
always_comb begin
    case (state)
        4'b0001: next_state = 4'b0001;
        4'b0010: next_state = 4'b0010;
        4'b0100: next_state = 4'b0100;
        4'b1000: next_state = 4'b1000;
        4'b0011: next_state = 4'b0010;
        4'b0110: next_state = 4'b0100;
        4'b1100: next_state = 4'b1000;
        4'b1111: next_state = 4'b0010;
        default: next_state = state;
    endcase
end

endmodule

