module TopModule(a, b, c, d, out);

    // Use combinatorial logic to generate the output
    always @(*) begin
        // Use a case statement to evaluate the Karnaugh map
        case (a && b && c && d)
            0: out = 0;
            1: out = (b && c && d) || (a && c && d) || (a && b && d);
            default: out = 1;
        endcase
    end

