reg [1:0] result[2:0];
assign result[0] = (x3 == 0) && (x2 == 0) ? 0 : (x3 == 0) && (x2 == 1) ? 1 : (x3 == 1) ? 0 : 1;
assign result[1] = (x3 == 0) && (x2 == 1) ? 1 : (x3 == 1) && (x2 == 0) ? 0 : (x3 == 1) && (x2 == 1) ? 1 : 0;
assign result[2] = (x3 == 0) && (x1 == 1) ? 1 : (x3 == 1) && (x1 == 0) ? 0 : (x3 == 1) && (x1 == 1) ? 1 : 0;

// Write the output f based on the result array
