module TopModule(clk, j, k, Q);
    reg [1:0] Qold;
    wire [1:0] nextQ;

    always_ff @(posedge clk) begin
        // Update Q old
        Qold <= nextQ;

        // Update nextQ
        if (~j && ~k) begin
            // No change
            nextQ <= Qold;
        elseif (~j && k) begin
            // Q toggles to old value
            nextQ <= ~Qold;
        elseif (j && ~k) begin
            // Q remains same
            nextQ <= Qold;
        else begin
            // Q toggles
            nextQ <= ~Qold;
        end
    end

    assign Q = nextQ;
endmodule

