module TopModule (
    input  clk,
    input  j,
    input  k,
    output Q
);

    // Define a local variable to hold the Q output
    reg Q_reg;

    // JK flip-flop logic
    always @(posedge clk) begin
        if (j && k) Q_reg <= ~Q_reg;  // Set Q to the opposite of Q_reg on both J and K
        else if (j) Q_reg <= 1'b1;  // Set Q to 1 when only J is high
        else if (k) Q_reg <= 1'b0;  // Set Q to 0 when only K is high
        else Q_reg <= Q_reg;  // No change if neither J nor K is high
    end

    // Assign Q_reg to Q
    assign Q = Q_reg;

endmodule

