module TopModule (
    input clk,
    input reset,
    output reg [3:0] q
);

    // Logic to count from 0 to 9 with a period of 10
    reg [3:0] counter;
    reg [1:0] count_counter;

    // Initial state of the counter
    initial begin
        counter = 0;
        count_counter = 0;
    end

    // Logic to update the counter
    always @(posedge clk) begin
        if (reset == 1) begin
            counter = 0;
            count_counter = 0;
        end else begin
            // Update the counter logic
            case (count_counter)
                0: begin
                    if (counter == 9) begin
                        counter = 0;
                        count_counter = 1;
                    end else begin
                        counter = counter + 1;
                    end
                end
                1: begin
                    if (counter == 9) begin
                        counter = 0;
                        count_counter = 0;
                    end else begin
                        counter = counter + 1;
                    end
                end
                2: begin
                    if (counter == 9) begin
                        counter = 0;
                        count_counter = 0;
                    end else begin
                        counter = counter + 1;
                    end
                end
                3: begin
                    if (counter == 9) begin
                        counter = 0;
                        count_counter = 0;
                    end else begin
                        counter = counter + 1;
                    end
                end
                default: begin
                    counter = 0;
                    count_counter = 0;
                end
            endcase

            // Update the count_counter
            count_counter = count_counter + 1;
        end
    end

    // Assign the final value of the counter to q
    always @(posedge clk) begin
        if (reset == 1) begin
            q = 4'b0000;
        end else begin
            q <= counter;
        end
    end

endmodule

