module TopModule (
    input clk,
    input reset,
    output reg [3:0] q,
    output reg [2:0] ena
);

    // Counter logic
    reg [3:0] counter;
    reg [2:0] enable;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 4'b0000;
            enable <= 3'b000;
        end else begin
            if (counter < 9) begin
                counter <= counter + 1'b1;
                enable <= 3'b111;
            end else begin
                counter <= 4'b0000;
                enable <= 3'b000;
            end
        end
    end

    // Ena logic
    always @(posedge clk) begin
        if (enable[0] && counter >= 9) begin
            ena <= ena + 1'b1;
        end
    end

    // Output logic
    always @(*) begin
        q[0] = counter[0];
        q[1] = counter[1];
        q[2] = counter[2];
        q[3] = counter[3];

        ena[0] = (q[1] == 4'b1111) && (q[2] == 4'b1111) && (q[3] == 4'b1111);
        ena[1] = (q[2] == 4'b1111) && (q[3] == 4'b1111);
        ena[2] = (q[3] == 4'b1111);
    end

endmodule

