module TopModule (
    input clk,
    input reset,
    output reg [3:0] q,
    output reg ena
);

    reg [3:0] counter = 0;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            ena <= 0;
        end else begin
            if (counter < 9999) begin
                counter <= counter + 1;
                ena <= 0; // Enable is high only when there's a digit to increment
            end else begin
                counter <= 0;
                ena <= 0; // When counter reaches 9999, reset the counter and disable the counter
            end
        end
    end

    // Convert counter to BCD
    reg [3:0] ones = counter[3:0];
    reg [3:0] tens = counter[7:4];
    reg [3:0] hundreds = counter[11:8];
    reg [3:0] thousands = counter[15:12];

    // Output BCD
    assign q = ((thousands << 4) | (hundreds << 0) | (tens << 4) | ones);

    // Outputs for upper three digits
    assign ena = (thousands != 9) || (hundreds != 9) || (tens != 9);
endmodule

