module TopModule (
    input  clk,
    input  w,
    input  R,
    input  E,
    input  L,
    output Q
);

// Define the shift register stage
reg [7:0] shift_register;

always @(posedge clk) begin
    if (E && !L) begin
        // Load new value into shift register
        shift_register <= w;
    end else if (R) begin
        // Shift register shift left
        reg [7:0] shifted = {w, shift_register[7:1]};
        shift_register <= shifted;
    end else begin
        // Shift register do not shift
        shift_register <= shift_register;
    end
end

always @(posedge clk) begin
    // Output Q is the least significant bit of the shift register
    Q <= shift_register[0];
end

endmodule

