reg [3:0] msel;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        msel <= 4'b0000;
    end else begin
        // Determine the index of the selected input
        case (sel)
            8'b0000: msel <= 4'b0000;
            8'b0001: msel <= 4'b0001;
            8'b0010: msel <= 4'b0010;
            8'b0011: msel <= 4'b0011;
            8'b0100: msel <= 4'b0100;
            8'b0101: msel <= 4'b0101;
            8'b0110: msel <= 4'b0110;
            8'b0111: msel <= 4'b0111;
            8'b1000: msel <= 4'b1000;
            8'b1001: msel <= 4'b1001;
            8'b1010: msel <= 4'b1010;
            8'b1011: msel <= 4'b1011;
            8'b1100: msel <= 4'b1100;
            8'b1101: msel <= 4'b1101;
            8'b1110: msel <= 4'b1110;
            8'b1111: msel <= 4'b1111;
            default: msel <= 4'b0000;
        endcase
    end
end

// Output the selected bits
assign out = in[msel];

