module TopModule(
    input clk,
    input in [7:0],
    output reg [7:0] anyedge
);

// Instantiate a register for each bit in the input vector
reg [7:0] anyedge_r[8:0];
always @(posedge clk) begin
    // Update the register values on the rising edge of the clock
    anyedge_r[0] = in[0];
    for (int i = 1; i < 8; i++) begin
        anyedge_r[i] = anyedge_r[i-1];
    end
    anyedge_r[8] = 1'b0;
end

always @(*) begin
    // Calculate the any edge values
    anyedge[0] = anyedge_r[1] != anyedge_r[0];
    for (int i = 1; i < 8; i++) begin
        anyedge[i] = anyedge_r[i+1] != anyedge_r[i];
    end
    anyedge[8] = 1'b0;
end

