    input areset,
    input [7:0] d,
    output [7:0] q
);

    // D flip-flop instantiation
    DFF[7:0] dut[8];

    // DFF reset logic
    wire [7:0] rst_d = areset ? 8'z : dut[7].q;

    // DFF clock logic
    wire rst_clk = (areset || dut[7].q) ? 1'b0 : 1'b1;

    // Assign DFFs
    dut[0].D = d[7];
    dut[0].Q = dut[0].Q;
    dut[1].D = d[6];
    dut[1].Q = dut[1].Q;
    dut[2].D = d[5];
    dut[2].Q = dut[2].Q;
    dut[3].D = d[4];
    dut[3].Q = dut[3].Q;
    dut[4].D = d[3];
    dut[4].Q = dut[4].Q;
    dut[5].D = d[2];
    dut[5].Q = dut[5].Q;
    dut[6].D = d[1];
    dut[6].Q = dut[6].Q;
    dut[7].D = d[0];
    dut[7].Q = rst_d;

    // Assign q
    q <= rst_clk ? dut[7].Q : 8'z;

