    input clk,

    // Enable shift
    input w,

    // Load input (only active during clock edge)
    input R,

    // Load signal
    input L,

    // Output of the stage
    output Q
);

    // Internal state (Q)
    reg[1:0] Q;

    always @(posedge clk) begin
        // Reset the state on the positive edge of the clock
        if (~R) begin
            Q <= 2'b00;
        end else begin
            // Shift the state one bit to the left
            Q <= w;
        end
    end

    always @ (R L) begin
        // If L is asserted, load the state with the input value
        if (L) begin
            Q <= R;
        end
    end

    assign Q_out = Q;
endmodule

