    input byteena[1:0],
    input [15:0] d,
    output [15:0] q
);

    reg [15:0] q[15:0];
    reg [15:0] d_[15:0];

    always @(posedge clk) begin
        if (!resetn) begin
            q[15:0] <= 0;
            d_[15:0] <= 0;
        end else begin
            for (int i = 0; i < 16; i++) begin
                q[i] <= q[i] ? d_[i] : 0;
                d_[i] <= d[i];
            end
        end
    end

    assign q = q[0:8];
    assign q[8:15] = q[8:15];

