    always @(posedge clk) begin
        if (!resetn) begin
            byteena[1:0] <= 0;
        end else begin
            byteena[1] <= d_[15];
            byteena[0] <= d_[14];
        end
    end

    // Control byte enable for d_[14:0]
    always @(posedge clk) begin
        if (!resetn) begin
            byteena[1:0] <= 0;
        end else begin
            byteena[1] <= d_[15];
            byteena[0] <= d_[14];
        end
    end

