module TopModule(
    input a, 
    input b, 
    input c, 
    input d, 
    input e, 
    output reg[24:0] out
    );

    // Compute all 25 pairwise one-bit comparisons
    for (int i = 0; i < 25; i++) {
        // Calculate ~a & b
        out[i] = (~a & b) | (~b & a);
    }

    // Compute all 25 pairwise one-bit comparisons for other pairs
    for (int i = 0; i < 25; i++) {
        if (i != 0) {
            // Calculate ~a & c
            out[i] = out[i] | (~a & c) | (~c & a);
            // Calculate ~a & d
            out[i] = out[i] | (~a & d) | (~d & a);
            // Calculate ~a & e
            out[i] = out[i] | (~a & e) | (~e & a);
            // Calculate ~b & c
            out[i] = out[i] | (~b & c) | (~c & b);
            // Calculate ~b & d
            out[i] = out[i] | (~b & d) | (~d & b);
            // Calculate ~b & e
            out[i] = out[i] | (~b & e) | (~e & b);
            // Calculate ~c & d
            out[i] = out[i] | (~c & d) | (~d & c);
            // Calculate ~c & e
            out[i] = out[i] | (~c & e) | (~e & c);
            // Calculate ~d & e
            out[i] = out[i] | (~d & e) | (~e & d);
        }
    }

endmodule

