module TopModule(
    input  a,
    input  b,
    input  c,
    input  d,
    output out
);

    reg[2:0] state;
    reg [3:2] temp;

    always @(*) begin
        // Initialize state with all ones
        state = 3'b111;

        // Determine next state based on current state and input
        case(state)
            3'b111: // reset state
                if(a && b && c && d) state = 3'b101;
                else if(a && b && c && !d) state = 3'b100;
                else if(a && !b && c && d) state = 3'b010;
                else if(a && !b && c && !d) state = 3'b001;
                else if(!a && b && c && d) state = 3'b110;
                else if(!a && b && c && !d) state = 3'b111;
                else if(!a && !b && c && d) state = 3'b101;
                else if(!a && !b && c && !d) state = 3'b100;
                else state = 3'b111;
            3'b101: // state 1
                if(a && c && !d) state = 3'b011;
                else if(!a && c && !d) state = 3'b111;
                else if(a && !c && !d) state = 3'b011;
                else if(!a && !c && !d) state = 3'b100;
                else state = 3'b101;
            3'b100: // state 2
                if(a && !d) state = 3'b110;
                else if(!a && !d) state = 3'b101;
                else if(a && !d && !c) state = 3'b110;
                else if(!a && !d && !c) state = 3'b100;
                else state = 3'b100;
            3'b010: // state 3
                if(a && !c && d) state = 3'b110;
                else if(!a && !c && d) state = 3'b011;
                else if(!a && !c && !d) state = 3'b101;
                else if(a && !c && !d) state = 3'b100;
                else state = 3'b010;
            3'b001: // state 4
                if(a && c && d) state = 3'b011;
                else if(!a && c && d) state = 3'b100;
                else if(a && c && !d) state = 3'b011;
                else if(!a && c && !d) state = 3'b100;
                else state = 3'b001;
            3'b110: // state 5
                if(!a && c && d) state = 3'b101;
                else if(a && c && d) state = 3'b100;
                else if(!a && c && !d) state = 3'b101;
                else if(a && c && !d) state = 3'b100;
                else state = 3'b110;
            3'b111: // state 6
                if(!a && d) state = 3'b100;
                else if(a && d) state = 3'b100;
                else if(!a && d && c) state = 3'b101;
                else if(a && d && c) state = 3'b100;
                else state = 3'b111;
            default:
                state = 3'b111;
        endcase
    end

    // Determine output based on current state
    always @(*) begin
        temp = state;
        case(temp)
            3'b111: // reset
                out = 1'b0;
                break;
            3'b101: // state 1
                out = 1'b1;
                break;
            3'b100: // state 2
                out = 1'b1;
                break;
            3'b010: // state 3
                out = 1'b1;
                break;
            3'b001: // state 4
                out = 1'b0;
                break;
            3'b110: // state 5
                out = 1'b0;
                break;
            3'b111: // state 6
                out = 1'b1;
                break;
            default:
                out = 1'b0;
        endcase
    end

endmodule

