module TopModule (
    input clk,
    input resetn,
    input byteena (2 bits),
    input d (16 bits),
    output q (16 bits)
);

    // Declare 16 D flip-flops
    reg [15:0] d_ff [0:15];

    // Clock and reset for D flip-flops
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            for (int i = 0; i < 16; i = i + 1) begin
                d_ff[i] <= 16'b0; // Initialize all DFFs to 0
            end
        end else begin
            // Apply byte enable
            if (byteena[0] == 1'b1) begin
                d_ff[0] <= d[7:0];
            end else begin
                d_ff[0] <= d[15:8];
            end
            if (byteena[1] == 1'b1) begin
                d_ff[1] <= d[15:8];
            end else begin
                d_ff[1] <= d[7:0];
            end
            // Apply the rest of the DFFs
            for (int i = 2; i < 16; i = i + 1) begin
                d_ff[i] <= d_ff[i - 1];
            end
        end
    end

    // Output the result of the D flip-flops
    assign q = {d_ff[15:8], d_ff[7:0]};

endmodule

