    reg [7:0] anyedge;

    always_comb begin
        // Create 8-bit output
        anyedge = ~(in) & prev_in;
        // Create a 9th bit for the previous state
        anyedge[8] = prev_in[0];
    end

    always_comb begin
        // Create 8-bit output
        if (in != prev_in) begin
            // If the input changes
            anyedge = in;
        end else begin
            // If the input doesn't change
            anyedge = 0;
        end
    end

