module TopModule (
    input  clk,
    input  j,
    input  k,
    output Q
);

    // JK Flip-Flop Truth Table
    // Qold is the output of the flip-flop before the positive clock edge

    // Define Qold as a wire to store the state of the flip-flop before the clock
    wire Qold;

    // Implement the JK Flip-Flop using a simple counter
    reg [1:0] counter;

    always @(posedge clk) begin
        if (j == 1) begin
            counter <= counter + 1;
        end
        if (k == 1) begin
            counter <= counter - 1;
        end

        // Determine Q based on the flip-flop's state
        if (counter == 0) begin
            Q <= 1'b0;
        end else if (counter == 1) begin
            Q <= 1'b1;
        end else if (counter == 2) begin
            Q <= Qold;
        end else begin
            Q <= ~Qold;
        end
    end

    // Connect Qold to the flip-flop's state
    assign Qold = counter;

endmodule

