module TopModule(
    input  logic [1023:0] in,
    input  logic [7:0] sel,
    output logic [3:0] out
);

    parameter num_inputs = 256;
    parameter num_bits = 4;
    parameter num_selects = 8;

    logic [num_bits - 1:0][num_inputs - 1:0] multiplexer [
        .sel  (sel[7:0]),
        .input(in[1023:20]),
        .output({out, out[3], out[2], out[1], out[0]})
    ];

    always_comb begin
        for (int i = 0; i < num_selects; i++) begin
            for (int j = 0; j < num_inputs; j++) begin
                if (j == i) begin
                    multiplexer[i][j] = 1;
                end else begin
                    multiplexer[i][j] = 0;
                end
            end
        end
    end

endmodule

