module TopModule(
    input mode,            // Mode of operation (heating or cooling)
    input too_cold,        // Temperature too cold
    input too_hot,         // Temperature too hot
    input fan_on,          // Request to turn on fan
    output heater,         // Control signal for heater
    output aircon,         // Control signal for air conditioner
    output fan             // Control signal for fan
);

// Define a type for the thermostat mode
typedef enum bit[1:0] {
    HEAT,                  // Heating mode
    COOL                   // Cooling mode
} ThermostatMode;

// Define a type for the fan state
typedef enum bit[1:0] {
    OFF,                   // Fan is off
    ON                    // Fan is on
} FanState;

// Initialize the fan state to off
assign fan = OFF;

// Initialize the heater and aircon states to off
assign heater = OFF;
assign aircon = OFF;

// Thermostat mode is initially set to COOL (no action)
ThermostatMode thermostat_mode = COOL;

// Update the thermostat mode based on the input mode
always @(posedge mode) begin
    if (mode == HEAT) {
        thermostat_mode = HEAT;
    } else {
        thermostat_mode = COOL;
    }
end

// Turn on the heater when it's too cold and in heating mode
always @(posedge mode) begin
    if (too_cold && thermostat_mode == HEAT) {
        heater <= ON;
    } else {
        heater <= OFF;
    }
end

// Turn on the aircon when it's too hot and in cooling mode
always @(posedge mode) begin
    if (too_hot && thermostat_mode == COOL) {
        aircon <= ON;
    } else {
        aircon <= OFF;
    }
end

// Turn on the fan when the heater, aircon, or fan_on inputs are high
assign fan = fan_on || heater || aircon;

// Output the fan state
assign fan = FanState(fan);

// Output the heater and aircon states
assign heater = FanState(heater);
assign aircon = FanState(aircon);

endmodule

