    parameter WIDTH = 4
  )
  (input clk,
   input reset,
   output [2:0] ena,
   output [15:0] q
   );

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 0;
      ena <= 0;
    end else begin
      integer digit;
      for (digit = WIDTH - 1; digit >= 0; digit--) begin
        if (digit == 0) begin
          q[15:10] <= q[14:10] + 1;
        end
        if (digit == 1) begin
          q[15:10] <= q[14:10] + 1;
          q[9:4] <= q[8:4] + 1;
        end
        if (digit == 2) begin
          q[15:10] <= q[14:10] + 1;
