module TopModule (
    input clk,
    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output [15:0] q
);

  // 16 D flip-flops
  reg [15:0] dff [0:15];

  // Control signals
  wire [1:0] de [0:15];
  wire [15:0] dff_output [0:15];

  // Process to control the control signals
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      // Reset all DFFs to their initial state
      dff <= 16'b0;
      de <= 16'b0;
    end else begin
      // Control the de and dff_output signals
      for (int i = 0; i < 16; i++) begin
        de[i] = byteena[i];  // Set de based on byteena
        dff_output[i] = d;  // Set dff_output based on d
      end
    end
  end

  // Process to update the DFFs based on de and dff_output
  always @(posedge clk or posedge resetn) begin
    if (resetn) begin
      // Reset all DFFs to their initial state
      dff <= 16'b0;
    end else begin
      // Update the DFFs based on de and dff_output
      for (int i = 0; i < 16; i++) begin
        if (de[i] == 1) begin
          dff[i] <= dff_output[i];
        end
      end
    end
  end

  // Output the result of the 16 D flip-flops
  assign q = dff;

endmodule

