module TopModule(
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

    // Define the state of the shift register
    reg[1:0] state;

    // Initialize the state to zero
    initial begin
        state = 2'b00;
    end

    // Update the state on the positive edge of the clock
    always @(posedge clk) begin
        if (L) begin
            state <= R;
        end else if (E) begin
            if (state[1] == 1'b1) begin
                state <= state;
            end else if (state[0] == 1'b1) begin
                state <= 2'b01;
            end else if (state[0] == 0'b1) begin
                state <= 2'b10;
            end else begin
                state <= 2'b11;
            end
        end else begin
            state <= state;
        end
    end

    // Output the current state of the shift register
    assign Q = state;

endmodule

