module TopModule(in, state, next_state, out);
    // State transition table
    typedef enum logic[4:0] states_t { A, B, C, D } states_t;
    states_t states = $signed(state);

    // State transition logic
    always_comb begin
        next_state[0] = (states == A) ? (states == A) : (states == D);
        next_state[1] = (states == B) ? (states == B) : (states == C);
        next_state[2] = (states == C) ? (states == A) : (states == B);
        next_state[3] = (states == D) ? (states == C) : (states == B);
    end

    // Output logic
    always_comb begin
        out = (states == A) ? (1'b0) : (states == B) ? (1'b0) : (states == C) ? (1'b1) : (states == D) ? (1'b1) : (1'b0);
    end
endmodule

