module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

    reg [3:0] digits;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    reg [1:0] increment;

    always @(posedge clk or negedge reset) begin
        if (reset) begin
            digits <= 0;
            tens <= 0;
            hundreds <= 0;
            thousands <= 0;
            increment <= 1'b0;
        end else begin
            if (increment == 2'b01) begin
                if (digits < 3) begin
                    digits <= digits + 1;
                    if (digits == 4) digits <= 0;
                    if (digits == 3) increment <= 2'b01;
                    if (digits == 2) increment <= 2'b10;
                end
            end
            if (increment == 2'b10) begin
                if (tens < 3) begin
                    tens <= tens + 1;
                    if (tens == 4) tens <= 0;
                    if (tens == 3) increment <= 2'b01;
                    if (tens == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b11) begin
                if (hundreds < 3) begin
                    hundreds <= hundreds + 1;
                    if (hundreds == 4) hundreds <= 0;
                    if (hundreds == 3) increment <= 2'b01;
                    if (hundreds == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b00) begin
                if (thousands < 3) begin
                    thousands <= thousands + 1;
                    if (thousands == 4) thousands <= 0;
                    if (thousands == 3) increment <= 2'b00;
                    if (thousands == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b01) begin
                if (thousands < 3) begin
                    thousands <= thousands + 1;
                    if (thousands == 4) thousands <= 0;
                    if (thousands == 3) increment <= 2'b00;
                    if (thousands == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b10) begin
                if (hundreds < 3) begin
                    hundreds <= hundreds + 1;
                    if (hundreds == 4) hundreds <= 0;
                    if (hundreds == 3) increment <= 2'b00;
                    if (hundreds == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b11) begin
                if (tens < 3) begin
                    tens <= tens + 1;
                    if (tens == 4) tens <= 0;
                    if (tens == 3) increment <= 2'b00;
                    if (tens == 2) increment <= 2'b00;
                end
            end
            if (increment == 2'b00) begin
                if (digits < 3) begin
                    digits <= digits + 1;
                    if (digits == 4) digits <= 0;
                    if (digits == 3) increment <= 2'b00;
                    if (digits == 2) increment <= 2'b00;
                end
            end
        end
    end

    always @(posedge clk or negedge reset) begin
        if (reset) begin
            q <= 16'd0;
        end else begin
            if (increment != 2'b00) begin
                q <= {thousands, hundreds, tens, digits};
            end else
                q <= (digits == 0 ? 16'd0 : 16'd16);
        end
    end

    always @(posedge clk or negedge reset) begin
        if (reset) begin
            ena <= 3'b000;
        end else begin
            ena <= (increment != 2'b00 ? 3'b1 : 3'b0);
        end
    end

endmodule

