    input clk,
    input w, // input from the prevous stage of the shift register
    input R, // input for value to load
    input E, // for enabling shift
    input L, // asserted when it should load
    output Q // Q is the output from the shift register
);

reg [7:0] shift_register; // 8-bit shift register

always @(posedge clk) begin
    if (E) begin
        // Shift register update logic
        if (R) begin
            // Load input value into shift register
            shift_register <= w;
        end
        // Shift operation
        if (L) begin
            // Shift the shift register left by one bit
            shift_register <= {shift_register[6:0], shift_register[7]};
        end
    end
