module TopModule(
    input  a, b, c, d, e,
    output  out
);

    always @(*) begin
        for (int i = 0; i < 25; i++) begin
            int mask = (i / 5) << 3;
            mask |= (i % 5) << (3 - (i % 5));
            if (mask == 0) mask = 1 << (mask + 4);
            out[i] = (~a & mask) | (~b & mask) | (~c & mask) | (~d & mask) | (~e & mask);
        end
    end

