// State transition table
always_comb begin
    case(state)
        4'd0: next_state = 4'd0;
        4'd1: next_state = 4'd1;
        4'd2: next_state = 4'd2;
        4'd3: next_state = 4'd3;
    endcase

    // Output logic: only non-zero states produce a non-zero output
    case(next_state)
        4'd0:   out = 0;
        4'd1:   out = 0;
        4'd2:   out = 0;
        4'd3:   out = 1;
    endcase
end

