module TopModule (
    input clk,
    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output [15:0] q
);

  // 16 D flip-flops
  reg [15:0] dff [0:15];

  // Control signals
  wire [1:0] feq;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      dff <= 0;
      feq <= 0;
    end else begin
      // Update DFFs based on byte-enable and D input
      for (int i = 0; i < 16; i++) begin
        if (byteena[i] && !feq[i]) begin
          dff[i] <= d;
          feq[i] <= 1;
        end else if (feq[i]) begin
          // DFFs stay unchanged if feq[i] is 1
          dff[i] <= dff[i];
        end else begin
          dff[i] <= dff[i];
        end
      end
    end
  end

  // Output the updated DFFs
  assign q = dff;

endmodule

