module TopModule(
    input clk,
    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output [15:0] q
);

// Instantiate 16 D flip-flops
reg [15:0] q[0:15];

always @(posedge clk) begin
    if (!resetn) begin
        // Initialize all q values to 0
        q[0:15] <= 0;
    end else begin
        // Write lower byte to DFFs with byteena[0] == 1
        if (byteena[0] == 1) begin
            // Lower byte DFFs
            for (int i = 0; i < 8; i++) begin
                // Write DFF[7:i] with D[7-i]
                if (d[7-i] == 1) q[i+7] <= 1;
            end
        end else begin
            // Write lower byte DFFs
            for (int i = 0; i < 8; i++) begin
                // DFF[7:i] always 0
                if (d[7-i] == 1) q[i+7] <= 1;
            end
        end

        // Write upper byte to DFFs with byteena[1] == 1
        if (byteena[1] == 1) begin
            // Upper byte DFFs
            for (int i = 8; i < 16; i++) begin
                // Write DFF[i] with D[i]
                if (d[i] == 1) q[i] <= 1;
            end
        end else begin
            // Write upper byte DFFs
            for (int i = 8; i < 16; i++) begin
                // DFF[i] always 0
                if (d[i] == 1) q[i] <= 1;
            end
        end
    end
end

// Reset all q values when resetn is active
always @(posedge resetn) q[0:15] <= 0;

endmodule

