);

    assign sum[1] = (select == 2'b00) ? a[0] : 0;
    assign sum[0] = (select == 2'b01) ? a[1] : 0;
    assign sum[0] += (select == 2'b10) ? b[0] : 0;
    assign sum[1] += (select == 2'b11) ? b[1] : 0;
    assign cout = (select == 2'b00) ? a[1] & b[1] & cin[0] : (select == 2'b01) ? a[0] & b[0] & cin[1] : 0;
    assign cout += (select == 2'b10) ? (a[0] | b[0]) & cin[0] : (a[1] | b[1]) & cin[1];
    assign cout += (select == 2'b11) ? (a[1] | b[1]) & cin[1] : (a[0] | b[0]) & cin[0];

