module TopModule(
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

// Create a state variable for each bit of the input vector
reg [7:0] states[8];

// Create a counter for each bit to track when the edge occurs
reg [7:0] edge_count[8];

// Initialize the state variable to the current input value
always @(posedge clk) for (int i = 0; i < 8; i++)
    states[i] <= in[i];

// Detect edge and update state variable
always @(posedge clk) for (int i = 0; i < 8; i++)
    if (states[i] != i) { // 0 to 1 or 1 to 0 transition
        states[i] <= 1'b1;
        states[i] <= i; // Reset state for next clock cycle
        edge_count[i] <= 8'b00000000;
    } else {
        states[i] <= i; // No transition, no edge
    }

// Update edge_count for the next clock cycle
always @(posedge clk) for (int i = 0; i < 8; i++)
    if (states[i] == 1'b1) { // Edge detected
        edge_count[i] <= edge_count[i] + 1;
    }

// Set anyedge to 1 on the next clock cycle after the edge occurs
assign anyedge = edge_count[0];

endmodule

