// State register
reg [2:0] state;

// Output values based on current state
reg out_value;

// Karnaugh map
assign out_value = case(state)
    0: a && b && c && d,
    1: a && b && !c && !d,
    2: !a && b && !c && d,
    3: !a && b && !c && !d,
    default: 0;
endcase;

// State transitions
always @(*) begin
    case(state)
        0: if(a && b && c && d) state = 0;
        else if(!a && b && !c && d) state = 3;
        else if(a && b && c && !d) state = 1;
        else if(!a && b && !c && !d) state = 2;
        else state = 0;
    endcase
end

// Output
assign out = out_value;

// Reset
assign state = 0;

// Testbench
