    reg [1:0] temp_carry;
    reg [1:0] temp_out;

    always @(posedge a or posedge b or posedge cin) begin
        temp_sum = (a & cin) ^ (b & cin) ^ (a & b);
        temp_carry = (a & b & ~cin) | ((a & cin) & ~b) | ((b & cin) & ~a);
        temp_out = temp_sum | temp_carry;

        if (temp_sum == 2) temp_sum = 1;
