module TopModule(
    input clk,
    input reset,
    output [3:0] q
);

// Define a module-level variable to store the current count
reg [9:0] count = 0;

// Define a module-level variable to store the counter state
reg [3:0] state = 0;

// Define a module-level variable to store the clock count
reg [9:0] clock_count = 0;

// Initialize the counter state to 0
always @(reset) 
    state <= 0;

// Clock process
always @(posedge clk) 
    begin
        // Update the clock count
        clock_count <= clock_count + 1;

        // Increment the state if the clock count is a multiple of 10
        if (clock_count % 10 == 0) 
            state <= 0;
        else 
            state <= state;

        // Increment the count if the state is greater than 0
        if (state > 0) 
            count <= count + 1;
        // Otherwise, reset the count
        else 
            count <= 0;

        // Shift the count to the left and select the least significant 4 bits
        if (clock_count % 10 == 0) 
            q <= state;
        else 
            q <= 4'd0;
    end

endmodule

