module TopModule (
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);

    // Define constants for modes
    localparam HEATING = 1'b1;
    localparam COOLING = 1'b0;

    // Define state variables
    reg [1:0] current_mode;
    reg [1:0] previous_mode;

    // State logic
    always @(posedge mode) begin
        current_mode <= mode;
    end

    // Control logic
    always @(posedge current_mode) begin
        case (current_mode)
            HEATING:
                if (too_cold && !aircon && !fan_on) begin
                    heater <= 1'b1;
                    aircon <= 1'b0;
                    fan <= 1'b1;
                end else if (!too_cold && !aircon) begin
                    heater <= 1'b1;
                    aircon <= 1'b0;
                end else begin
                    heater <= 1'b0;
                    aircon <= 1'b0;
                    fan <= 1'b0;
                end
            COOLING:
                if (too_hot && !heater && !fan_on) begin
                    heater <= 1'b0;
                    aircon <= 1'b1;
                    fan <= 1'b1;
                end else if (!too_hot && !heater) begin
                    heater <= 1'b0;
                    aircon <= 1'b1;
                end else begin
                    heater <= 1'b0;
                    aircon <= 1'b0;
                    fan <= 1'b0;
                end
            default:
                heater <= 1'b0;
                aircon <= 1'b0;
                fan <= 1'b0;
        endcase
    end

    // Fan control logic
    always @(posedge fan_on) begin
        if (current_mode == HEATING) begin
            heater <= 1'b1;
        end else if (current_mode == COOLING) begin
            aircon <= 1'b1;
        end else begin
            heater <= 1'b0;
            aircon <= 1'b0;
            fan <= 1'b1;
        end
    end

endmodule

