module TopModule(in, state, next_state, out);

    // Define the state encoding
    parameter A = 4'b0001;
    parameter B = 4'b0010;
    parameter C = 4'b0100;
    parameter D = 4'b1000;

    // State transition table
    reg [3:0] state_reg;
    reg [3:0] next_state_reg;
    assign state_reg = state;

    // Derive next state
    case(state_reg)
        A: next_state_reg = next_state_reg == A ? A : B;
        B: next_state_reg = next_state_reg == B ? B : C;
        C: next_state_reg = next_state_reg == C ? C : D;
        D: next_state_reg = next_state_reg == D ? D : A;
        default: next_state_reg = A;
    endcase

    // Output logic
    reg [3:0] out_reg;
    assign out_reg = next_state_reg == A ? 0 : 1;

    // State change logic
    assign next_state = next_state_reg;

    // Output assignment
    assign out = out_reg;
endmodule

