module TopModule(clk, reset, ena, q);

    // Input and output ports
    input clk;
    input reset;
    output [2:0] ena; // enables upper digits
    output [15:0] q;  // 4-digit BCD counter

    // Internal signals
    reg [1:0] count_digit; // current digit to be counted
    reg [1:0] count_step; // current step of counting
    reg [1:0] carry; // carry from lower digits
    reg [7:4] tens_digit; // tens digit of current digit
    reg [7:4] current_digit; // current digit being counted
    reg [3:0] ones_digit; // ones digit of current digit

    // Assign initial values
    initial begin
        count_digit = 0;
        count_step = 0;
        carry = 0;
        tens_digit = 0;
        current_digit = 0;
        ones_digit = 0;
    end

    always @(posedge clk) begin
        if (reset) begin
            // Reset all values to 0
            count_digit = 0;
            count_step = 0;
            carry = 0;
            tens_digit = 0;
            current_digit = 0;
            ones_digit = 0;
        end else begin
            // Increment counting steps
            count_step++;

            // If counting step exceeds 3, set carry to 1
            if (count_step == 3) begin
                carry = 1;
            end

            // If carry is 1, increment tens digit
            if (carry) begin
                tens_digit = tens_digit + 1;
                if (tens_digit > 3) begin
                    carry = 1;
                    tens_digit = 0;
                end
            end

            // If carry is 1, increment current digit
            if (carry) begin
                current_digit = current_digit + 1;
                if (current_digit > 9) begin
                    carry = 1;
                    current_digit = 0;
                end
            end

            // If carry is 1, increment ones digit
            if (carry) begin
                ones_digit = ones_digit + 1;
                if (ones_digit > 9) begin
                    carry = 1;
                    ones_digit = 0;
                end
            end

            // Update counting step for next iteration
            count_step = count_step & (count_digit == 0);

            // If counting step is 0, reset it
            if (count_step == 0) begin
                count_step = 1;
            end
        end
    end

    // Assign output signals
    assign ena = count_step;
    assign q = ones_digit * 10**4 + current_digit * 10**2 + tens_digit * 10 + carry * 10;

endmodule

