    end else if (fan_on) begin
        // Fan request
        heater <= 0;
        aircon <= 0;
        fan <= 1;  // Always turn on the fan when fan_on is high
    end else begin
        // Other conditions (e.g., no heater/aircon, no fan request)
        heater <= 0;
        aircon <= 0;
        fan <= 0;  // Turn off everything if none of the above conditions are met
    end
end

