module TopModule (
    input  a,  // 1-bit input
    input  b,  // 1-bit input
    input  c,  // 1-bit input
    input  d,  // 1-bit input
    input  e,  // 1-bit input
    output reg [24:0] out  // 25-bit output
);

    // 25-bit output vector initialized to zero
    reg [24:0] output_vector;

    always @(posedge clock) begin
        // Initialize the output vector to zero
        output_vector = 25'b0;

        // Compute all pairwise one-bit comparisons
        for (int i = 0; i < 25; i = i + 1) begin
            if (i < 13) begin
                output_vector[i] = ~a ^ a;
                output_vector[24 - i] = ~a ^ b;
                output_vector[24 - i + 1] = ~a ^ c;
                output_vector[24 - i + 2] = ~a ^ d;
                output_vector[24 - i + 3] = ~a ^ e;
            end else if (i < 21) begin
                output_vector[i] = ~b ^ b;
                output_vector[24 - i] = ~b ^ c;
                output_vector[24 - i + 1] = ~b ^ d;
                output_vector[24 - i + 2] = ~b ^ e;
            end else if (i < 29) begin
                output_vector[i] = ~c ^ c;
                output_vector[24 - i] = ~c ^ d;
                output_vector[24 - i + 1] = ~c ^ e;
            end else if (i < 37) begin
                output_vector[i] = ~d ^ d;
                output_vector[24 - i] = ~d ^ e;
            end else if (i < 45) begin
                output_vector[i] = ~e ^ e;
            end else begin
                // No additional comparisons for the last 11 bits
            end
        end

        // Assign the computed output vector to the 25-bit output port
        out <= output_vector;
    end

endmodule

