module TopModule(
    input clk,
    input a,
    input b,
    output out_assign,
    output out_always_comb,
    output out_always_ff
);

    always_comb begin
        // Combinational XOR with assign statement
        out_assign = a ^ b;
    end

    always_comb begin
        // Combinational XOR with always block
        out_always_comb = a ^ b;
    end

    always_ff @(posedge clk) begin
        // Clocked XOR with flip-flop and D flip-flop
        reg [1:0] prev_out;
        always_comb begin
            if (a) prev_out <= 1'b1;
            else prev_out <= 1'b0;
            if (b) prev_out <= 1'b1;
            else prev_out <= 1'b0;
        end
        reg [1:0] out_ff;
        assign out_always_ff = prev_out ^ a;
        assign out_ff = out_always_ff;
        assign out_always_ff = prev_out;
    end

endmodule

