    assign ringer = 0;
    assign motor = 0;

    // Assign the output value based on the ring and vibrate_mode inputs
    // When ring is 1, ringer is 1
    // When vibrate_mode is 1, motor is 1
    // When neither ring nor vibrate_mode is 1, ringer is 1 and motor is 0
    // This is a tautology, so it can be simplified to just one line
    assign ringer = (ring) ? 1 : vibrate_mode;

    // However, the task also says that the motor should be 1 when ring is 1
