module TopModule(
    input  in,
    input  state [3:0],
    output  next_state [3:0],
    output  out
);

    // Define the one-hot state encoding
    parameter A = 4'd0, B = 4'd1, C = 4'd2, D = 4'd3;

    // State transition table
    assign next_state = 
        {in,  state == A  ? A : state == B  ? B : state == C  ? C : D };

    // Output logic
    always @ (next_state)
        case (next_state)
            A: out = 1'b0;
            B: out = 1'b0;
            C: out = 1'b0;
            D: out = 1'b1;
            default: out = 1'b0;
        endcase;

endmodule

