module TopModule(clk, w, R, E, L, Q);

    reg [0:0] Q;
    reg [0:0] prev_w;
    reg [0:0] prev_R;

    always @(posedge clk) begin
        if (E) begin
            prev_R <= R;
            prev_w <= w;
        end
        else if (L) begin
            prev_R <= Q;
            prev_w <= Q;
        end
    end

    always @(posedge clk) begin
        if (prev_R != Q && prev_w != Q) begin
            Q <= prev_w;
        end
    end

endmodule

