module TopModule (
    input  clk,
    input  reset,
    output [3:0] ena,
    output [15:0] q
);

    // Declare the counters and enable signals
    reg [3:0] counter[0:3];
    reg [3:0] enable[0:3];

    // Synchronous Active-High Reset
    always @(posedge reset or posedge clk) begin
        if (reset) begin
            counter <= 4'b0000;
            enable <= 4'b0000;
        end else begin
            counter <= counter + 1'b1;
            enable <= enable + 1'b1;
        end
    end

    // Increment logic for each digit
    always @(posedge clk) begin
        for (integer i = 0; i < 4; i = i + 1) begin
            counter[i] <= (counter[i] == 4'b1111) ? 4'b0000 : counter[i] + 1'b1;
        end
    end

    // Output the counter digits
    assign q[15:12] = counter[3];
    assign q[11:8] = counter[2];
    assign q[7:4] = counter[1];
    assign q[3:0] = counter[0];

    // Enable signals for the upper three digits
    assign enable[3] = counter[3] == 4'b1111;
    assign enable[2] = counter[2] == 4'b1111;
    assign enable[1] = counter[1] == 4'b1111;

endmodule

