module TopModule(clk, a, b, out_assign, out_always_comb, out_always_ff);

    logic clk;
    logic a;
    logic b;
    logic out_assign;
    logic out_always_comb;
    logic out_always_ff;

    // Assign statement
    assign out_assign = !a & !b;

    // Combinational always block
    always_comb begin
        out_always_comb = a ^ b;
    end

    // Clocked always block with D flip flop
    logic out_ff;
    logic[1:0] q;
    DFlipFlop #(.DIN(!a & !b), .CIN(clk)) DFF(clk, q, out_ff);

    assign out_always_ff = q;

endmodule

