module DFlipFlop(DIN, CIN, Q, Q_out, clk);
    input logic DIN, CIN, clk;
    output logic[1:0] Q;
    output logic Q_out;

    always @(posedge clk) begin
        if(CIN) Q <= DIN;
        else if(!Q) Q <= 1'b1;
        else Q <= 1'b0;
    end

endmodule

