module TopModule(
    input a,  // 1-bit input
    input b,  // 1-bit input
    output out // 1-bit output
);

    always @(posedge a or posedge b) begin
        // Calculate the XOR of a and b
        // Since XNOR gate is the inverse of XOR gate, we use the following formula:
        // out = (a and not(b)) or (b and not(a))

        // Bit-wise AND operation
        assign a_and_not_b = a & (~b);

        // Bit-wise AND operation
        assign b_and_not_a = b & (~a);

        // Use XNOR operation to calculate the output
        assign out = a_and_not_b | b_and_not_a;

    end

endmodule

