module TopModule(
    input  in,
    input  [3:0] state,
    output  [3:0] next_state,
    output  out
);

    // Define the one-hot state encoding
    reg  [3:0] state_encoded;
    assign state_encoded = {state[2], state[1], state[0], 1'b0};

    // Define the state transition table
    reg  [3:0] next_state_encoded;
    assign next_state_encoded = {state == 4'b0010 : 'b1, 
                                state == 4'b0001 : 'b0, 
                                state == 4'b0100 : 'b0, 
                                state == 4'b1000 : 'b1};

    // Derive next state and output logic equations by inspection
    always @(*) begin
        case(next_state_encoded)
            'b0:  out <= 0;
            'b1:  out <= 1;
            default: $assert(false); // this should never happen
        endcase

        case(state)
            4'b0001:  next_state <= 'b0;
            4'b0010:  next_state <= 'b1;
            4'b0100:  next_state <= 'b0;
            4'b1000:  next_state <= 'b1;
            default: $assert(false); // this should never happen
        endcase
    end

endmodule

