module TopModule(
    input clk,
    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output [15:0] q
);

// Initialize 16 D flip-flops
reg [15:0] q[0:15];

// Create a clocked process for updating flip-flops
always_ff @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        // Reset all flip-flops
        q[0:15] <= 16'd0;
    end else begin
        // Update all flip-flops based on byteena
        for (int i = 0; i < 16; i++) begin
            if (byteena[0] == 1 && (i < 8)) begin
                // Write lower byte
                if (d[7 + i] == 16'd1) begin
                    q[i] <= q[i];
                end else begin
                    q[i] <= (d[7 + i]);
                end;
            end else if (byteena[1] == 1 && (i >= 8)) begin
                // Write upper byte
                if (d[15 + i] == 16'd1) begin
                    q[i] <= q[i];
                end else begin
                    q[i] <= (d[15 + i]);
                end;
            end
        end
    end
end

// Assign the output q to the q array
assign q = q[0:15];

endmodule

