module TopModule(a, b, c, d, out);

    wire ab, bc, cd, ac, bd, ad;
    assign ab = a & b;
    assign bc = b | c;
    assign cd = c & d;
    assign ac = a | c;
    assign bd = b | d;
    assign ad = a & d;

    wire y1, y2, y3, y4;
    assign y1 = ab & cd;
    assign y2 = ab | bc;
    assign y3 = ab | ac;
    assign y4 = ab | bd;

    assign out = (y1 & ~bc) | (~y2 & ~ac) | 
                  (y3 & ~bd) | (~y4 & ~ad);

endmodule

