    input clk,
    input resetn,
    input byteena [1:0],
    input [15:0] d,
    output reg [15:0] q
);

    // Define the D flip-flops
    reg [15:0] dff [15:0];

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            // Reset all D flip-flops to 0
            for (int i = 0; i <= 15; i = i + 1) begin
                dff[i] <= 16'b0;
            end
        end else begin
            // Update D flip-flops based on the byte-enable signals
            for (int i = 0; i <= 15; i = i + 1) begin
                if (byteena[1] & (i == 15) || byteena[0] & (i == 7)) begin
                    // Only write to the selected bytes
                    dff[i] <= d;
                end else begin
                    // Leave the other bits unchanged
                    dff[i] <= dff[i];
                end
            end
        end
    end

    // Assign the current value of the D flip-flops to the output
    assign q = dff;

endmodule

