    if (reset) begin
        ena_val = 0;
        q_val = 0;
    end else if (ena_val == 3'b000) begin
        q_val = $signed($signed(q_val) + 1);
    end else if (ena_val == 3'b001) begin
        q_val = $signed($signed(q_val) + 4'b0001);
        q_val = $signed($signed(q_val) + 4'b1000);
    end else if (ena_val == 3'b010) begin
        q_val = $signed($signed(q_val) + 4'b0001);
        q_val = $signed($signed(q_val) + 4'b1000);
        q_val = $signed($signed(q_val) + 4'b1001);
    end else if (ena_val == 3'b011) begin
        q_val = $signed($signed(q_val) + 4'b1000);
        q_val = $signed($signed(q_val) + 4'b1001);
        q_val = $signed($signed(q_val) + 4'b0001);
        q_val = $signed($signed(q_val) + 4'b1000);
    end else if (ena_val == 3'b100) begin
        q_val = $signed($signed(q_val) + 4'b1001);
        q_val = $signed($signed(q_val) + 4'b0001);
        q_val = $signed($signed(q_val) + 4'b1000);
        q_val = $signed($signed(q_val) + 4'b1000);
