module TopModule(
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

    // Define the state of the shift register
    reg[7:0] shiftReg;

    // Create a one-stage shift register
    always_ff @(posedge clk) begin
        if (!E) begin
            // Shift right by 1 bit
            shiftReg <= {1, shiftReg[7:2]};
        end else if (L) begin
            // Load the value
            if (R) begin
                shiftReg <= R;
            end else begin
                // Simply shift right
                shiftReg <= {1, shiftReg[7:2]};
            end
        end else begin
            // Do nothing
            shiftReg <= shiftReg;
        end
    end

    // Shift the value to the output
    assign Q = shiftReg[0];

endmodule

