module TopModule (
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

    // Signal to track the last state of the input signal
    reg [7:0] last_in = 8'b0;

    // Register to keep track of the current edge detect state
    reg [7:0] edge_detect = 8'b0;

    always @(posedge clk) begin
        // Update the last_in register
        last_in <= in;

        // Compare current input with last_in to detect any edge
        if (in != last_in) begin
            // If in is 0 to 1 or 1 to 0, set edge_detect to 1
            if (last_in == 8'b0 && in == 1'b1) begin
                edge_detect <= 8'b0;
            end else if (last_in == 8'b1 && in == 1'b0) begin
                edge_detect <= 8'b0;
            end else begin
                edge_detect <= 8'b1;
            end
        end else begin
            // If no edge detected, reset edge_detect to 0
            edge_detect <= 8'b0;
        end

        // Update anyedge with the current edge_detect state
        anyedge <= edge_detect;
    end

endmodule

