module TopModule(
    input  wire in,
    output reg [3:0] next_state,
    output reg [3:0] out
);

// State encoding
const int STATE_A = 4'b0001;
const int STATE_B = 4'b0010;
const int STATE_C = 4'b0100;
const int STATE_D = 4'b1000;

// State transition table
always @(*)
begin
    case(in)
        0 : next_state = STATE_A;
        1 : case(next_state)
            STATE_A : next_state = STATE_A;
            STATE_B : next_state = STATE_B;
            STATE_C : next_state = STATE_C;
            STATE_D : next_state = STATE_D;
    endcase;
end

// Output logic
always @(*)
begin
    case(next_state)
        STATE_A : out = 0;
        STATE_B : out = 0;
        STATE_C : out = 1;
        STATE_D : out = 1;
    endcase;
end

endmodule

