module TopModule (
    input wire in,
    input wire state,
    output wire next_state,
    output wire out
);

    parameter WIDTH = 4;
    reg [WIDTH-1:0] state_reg = 4'b0001;
    reg [WIDTH-1:0] next_state_reg;

    always @(posedge in) begin
        state_reg <= state;
    end

    always @(posedge state_reg or posedge in) begin
        next_state_reg <= case (state_reg)
            4'b0001: case (in)
                1'b0: next_state_reg <= 4'b0010;
                1'b1: next_state_reg <= 4'b0100;
            endcase
            4'b0010: case (in)
                1'b0: next_state_reg <= 4'b0001;
                1'b1: next_state_reg <= 4'b0100;
            endcase
            4'b0100: case (in)
                1'b0: next_state_reg <= 4'b0001;
                1'b1: next_state_reg <= 4'b0100;
            endcase
            4'b1000: case (in)
                1'b0: next_state_reg <= 4'b0001;
                1'b1: next_state_reg <= 4'b0100;
            endcase
        endcase
    end

    always @(posedge next_state_reg or posedge in) begin
        out <= case (next_state_reg)
            4'b0001: out <= 1'b0;
            4'b0010: out <= 1'b0;
            4'b0100: out <= 1'b0;
            4'b1000: out <= 1'b1;
        endcase
    end

endmodule

