    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
            state <= 2'b00;
        end else begin
            case (state)
                2'b00: begin
                    if (count == 4'b0009) begin
                        count <= 4'b0000;
                        state <= 2'b01;
                    end else begin
                        count <= count + 1'b1;
                    end
                end
                2'b01: begin
                    if (count == 4'b0009) begin
                        count <= 4'b0000;
                        state <= 2'b00;
                    end else begin
                        count <= count + 1'b1;
                    end
                end
                2'b10: begin
                    if (count == 4'b0009) begin
                        count <= 4'b0000;
                        state <= 2'b01;
                    end else begin
                        count <= count + 1'b1;
                    end
                end
                2'b11: begin
                    if (count == 4'b0009) begin
                        count <= 4'b0000;
                        state <= 2'b00;
                    end else begin
                        count <= count + 1'b1;
                    end
                end
                default: begin
                    state <= 2'b00;
                end
            endcase
        end
    end

    assign q = count;

