module TopModule (
    input  logic  in,
    input  logic  [3:0]  state,
    output logic [3:0]  next_state,
    output logic        out
);

    // State encoding for Moore state machine
    logic [1:0]  nextState1, nextState2, nextState3, nextState4;
    assign     nextState1 = state[1:0];
    assign     nextState2 = state[2:1];
    assign     nextState3 = state[3:2];
    assign     nextState4 = state[3:2] | state[1:0];

    // Moore state machine state transition logic
    logic [1:0]  nextState = `switch ((in ? 1 : 0)) {
        `define(A) nextState1;
        `define(B) nextState2;
        `define(C) nextState3;
        `define(D) nextState4;
    };

    // Output logic
    logic  outputLogic;
    always_comb begin
        if (nextState == nextState1) begin
            outputLogic = 0;
        end else if (nextState == nextState2) begin
            outputLogic = 0;
        end else if (nextState == nextState3) begin
            outputLogic = 0;
        end else if (nextState == nextState4) begin
            outputLogic = 1;
        end
    end

    // Output assignment
    assign  out = outputLogic;
    assign  next_state = nextState;

endmodule

