module TopModule(in, state, next_state, out);
    input in;
    input [3:0] state;
    output [3:0] next_state;
    output [1:0] out;

    always_comb begin
        // Determine the next state based on the current state and input
        case(state)
            4'b0001 : next_state = (in == 0) ? state : 4'b0010;
            4'b0010 : next_state = (in == 0) ? state : 4'b0100;
            4'b0100 : next_state = (in == 0) ? 4'b1000 : state;
            4'b1000 : next_state = (in == 0) ? state : 4'b0010;
        endcase

        // Determine the output based on the next state
        case(next_state)
            4'b0001 : out = 4'b0;
            4'b0010 : out = 4'b0;
            4'b0100 : out = 4'b0;
            4'b1000 : out = 4'b1;
        endcase
    end
endmodule

