module TopModule (
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);

    // Define the state transitions for the thermostat
    always @(posedge mode) begin
        case (mode)
            1: begin
                // If mode is heating, turn on heater and off aircon
                heater <= 1;
                aircon <= 0;
            end
            0: begin
                // If mode is cooling, turn on aircon and off heater
                heater <= 0;
                aircon <= 1;
            end
            default: begin
                // Default case, no action if mode is invalid
                heater <= 0;
                aircon <= 0;
            end
        endcase
    end

    // If fan_on is high, turn on the fan regardless of the thermostat mode
    always @(posedge fan_on) begin
        fan <= 1;
    end

endmodule

