module TopModule (
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

    reg [7:0] prev;
    reg [7:0] curr;
    reg Q;

    always @(posedge clk)
    begin
        if (E)
        begin
            if (R)
            begin
                if (L)
                begin
                    // Load value into Q
                    Q <= w;
                    // Reset prev to curr
                    prev <= curr;
                end else
                begin
                    // Shift bits to the left by 1
                    // and load value into Q
                    curr <= {w, curr[6:0]};
                    // Reset prev to curr
                    prev <= curr;
                end
            end else
            begin
                // Shift bits to the left by 1
                // and load value into curr
                curr <= {w, curr[6:0]};
                // Reset prev to curr
                prev <= curr;
            end
        end else
        begin
            // No shift
            Q <= prev;
        end
    end

endmodule

