module TopModule(x3, x2, x1, f);

    // Internal signals to hold the values of each bit
    reg [2:0] internal_state;

    // Combinational logic
    always @* begin
        // Reset the internal state to 0
        if (x3 == 0) begin
            internal_state = 0;
        end

        // Update the internal state based on the current inputs
        if (x3 && !x2 && x1) begin
            internal_state = internal_state | 2'0;
        end
        if (x3 && !x2 && !x1) begin
            internal_state = internal_state | 2'1;
        end
        if (x3 && x2 && !x1) begin
            internal_state = internal_state | 2'2;
        end
        if (x3 && x2 && x1) begin
            internal_state = internal_state | 2'3;
        end
        if (!x3 && x2 && x1) begin
            internal_state = internal_state | 2'4;
        end
        if (!x3 && x2 && !x1) begin
            internal_state = internal_state | 2'5;
        end
        if (!x3 && !x2 && x1) begin
            internal_state = internal_state | 2'6;
        end
        if (!x3 && !x2 && !x1) begin
            internal_state = internal_state | 2'7;
        end

        // Determine the output based on the internal state
        f <= (internal_state == 0'h7);

    end

endmodule

