    reg [2:0] bit2 = b[2];
    reg [2:0] sum_result = 0;

    // Full adder logic
    assign bit1 = bit2;
    assign sum_result[2] = a[2] | b[2] | cin;
    assign sum_result[1] = (a[1] & ~cin) | ((a[0] & b[2]) | (b[1] & cin));
    assign sum_result[0] = (a[0] & b[1]) | (a[1] & b[0]);

    // Output signals
