module TopModule(
    input clk,
    input reset,
    output reg [2:0] ena,
    output [15:0] q
);

reg [2:0] ena_c;
reg [15:0] q_c;
reg [2:0] carry;
reg [2:0] ones_digit;
reg [2:0] tens_digit;
reg [2:0] hundreds_digit;
reg [2:0] thousands_digit;

initial begin
    ena_c = 3'b000;
    q_c = 16'h0000;
    carry = 3'b000;
    ones_digit = 3'b000;
    tens_digit = 3'b000;
    hundreds_digit = 3'b000;
    thousands_digit = 3'b000;
end

always @(posedge clk or negedge reset)
begin
    if(reset)
        q_c = 16'h0000;
    else
    begin
        ones_digit <= carry;
        carry = 0;
        tens_digit <= (ena_c & ones_digit) ^ ones_digit;
        hundreds_digit <= (ena_c & tens_digit) ^ tens_digit;
        thousands_digit <= (ena_c & hundreds_digit) ^ hundreds_digit;
        q_c = (thousands_digit << 12) | (hundreds_digit << 8) | (tens_digit << 4) | ones_digit;
        ena_c <= 3'b000;
    end
end

assign q = q_c;
assign ena = ena_c;

endmodule

