module TopModule(clk, in, anyedge);

    // Inputs
    input clk;
    input [7:0] in;

    // Outputs
    output [7:0] anyedge;

    // Internal signals
    reg [7:0] prev_in;
    reg [7:0] next_in;
    reg [7:0] any_edge;

    // Initial values
    always @(start) prev_in <= 8'b0;
    always @(start) next_in <= 8'b0;
    always @(start) any_edge <= 8'b0;

    // Main logic
    always @(posedge clk) begin
        next_in <= in;
        any_edge <= any_edge;

        for (int i = 0; i < 8; i++) begin
            if (next_in[i] == 1'b0 && prev_in[i] == 1'b1) begin
                any_edge[i] <= 1'b1;
            end else if (next_in[i] == 1'b1 && prev_in[i] == 1'b0) begin
                any_edge[i] <= 1'b1;
            end else begin
                any_edge[i] <= 1'b0;
            end
        end

        prev_in <= next_in;
    end

    // Output assignment
    assign anyedge = any_edge;

endmodule

