        idxs[7] = sel[7:4] + 16'd12;
        idxs[6] = sel[6:4] + 16'd8;
        idxs[5] = sel[5:4] + 16'd4;
        idxs[4] = sel[4:2] + 16'd0;
        idxs[3] = sel[1:0] + 16'd0;
        idxs[2] = sel[3:1] + 16'd4;
        idxs[1] = sel[2:0] + 16'd8;
        idxs[0] = sel[1] + 16'd12;
    end

    always_comb begin
        case (sel)
            0 : begin
                out = {in[idxs[3]] , in[idxs[2]] , in[idxs[1]] , in[idxs[0]]};
            end
            1 : begin
                out = {in[idxs[7]] , in[idxs[6]] , in[idxs[5]] , in[idxs[4]]};
            end
            2 : begin
                out = {in[idxs[11]] , in[idxs[10]] , in[idxs[9]] , in[idxs[8]]};
            end
            default : begin
                out = '{0, 0, 0, 0};
            end
        endcase
    end
