    output [15:0] q
);
    reg [2:0] ena_count = 3'b000; // initial value of enable count
    reg [15:0] q_count = 16'h0000; // initial value of BCD count

    always @(posedge clk) begin
        if (reset) begin
            q_count <= 16'h0000;
            ena_count <= 3'b000;
        end else begin
            q_count <= q_count + 1;
            if (q_count == 16'h8000) begin // carry out
                q_count <= 16'h0000;
                if (ena_count >= 3'b100) begin // enable increment after BCD reset
                    ena_count <= 3'b000;
                end else if (ena_count == 3'b011) begin // enable increment after tens digit increment
                    ena_count <= 3'b001;
                end else begin // enable increment after hundreds digit increment
                    ena_count <= ena_count + 1;
                end
            }
        end
    end

    assign q = q_count[7:4] << 4 | q_count[3:0]; // BCD encoding
    assign ena = {ena_count[1], ena_count[0], ena_count[2]}; // enable signals

endmodule

