    input b,
    input c,
    input d,
    output out
);

    // Define the Karnaugh map
    reg [1:0] abc; // a, b, and c combined into a single 2-bit register
    reg      d;    // d as it is

    // Mapping the Karnaugh map to the output
    always @(a, b, c, d) begin
        // 00 -> 0
        if (a == 0 && b == 0 && c == 0) out = 1'b0;
        // 01 -> 1
        else if (a == 0 && b == 1 && c == 1) out = 1'b1;
        // 11 -> 1
        else if (a == 1 && b == 1 && c == 1) out = 1'b1;
        // 10 -> 0
        else if (a == 1 && b == 0 && c == 0) out = 1'b0;
        // Default case (if none of the conditions are met)
        else out = 1'b1;
    end

endmodule

