                else if (in == 1) next_state = 4'b0010;
                else next_state = 4'b0000;
            4'b0010:  // B
                if (in == 0) next_state = 4'b0010;
                else if (in == 1) next_state = 4'b0100;
                else next_state = 4'b0010;
