            default:  // State should be one of the above states
                // If state is not one of the above states, set it to the last state
                next_state = 4'b1000;
        endcase
    end

    // Output logic
    assign out[0] = state[3] != 0;  // A
    assign out[1] = state[2] != 0;  // B
