    // Map the Karnaugh map to the output
    case (ab)
        2'b00: cd = 2'b00;
        2'b01: cd = 2'b01;
        2'b11: cd = 2'b11;
        2'b10: cd = 2'b10;
        default: cd = 2'b00; // Default to 0 for invalid input combinations
    endcase

    // Map the CD output to the final output
    case (cd)
        2'b00: out_map[0] = 1'b1; // CD 00 -> out 1
        2'b01: out_map[1] = 1'b0; // CD 01 -> out 0
        2'b11: out_map[2] = 1'b1; // CD 11 -> out 1
