module TopModule (
    input wire clk,
    input wire w,
    input wire R,
    input wire E,
    input wire L,
    output reg Q
);

reg [7:0] state = 0; // current state of the shift register

always @(posedge clk) begin
    if (E) begin
        // enable shift
        case (state)
            0: state <= w;
            1: state <= state << 1;
            2: state <= state | w;
            default: state <= 0; // reset to 0 if unexpected state
        endcase
    end
    else begin
        // disable shift
        state <= state >> 1;
    end
end

