module TopModule(clk, areset, d, q);

    reg [7:0] q[7:0];
    reg [7:0] d[7:0];
    reg [7:0] dq[7:0];
    wire [7:0] q_next[7:0];

    // Asynchronous reset
    always @(posedge areset) begin
        dq[0:7] <= 8'd0;
        dq_next[0:7] <= 8'd0;
    end

    // D flip-flops
    for (int i = 0; i < 8; i++) begin : DFF
        DFF #(.M(1)) DFF_DQ(d[i], dq[i], dq_next[i], q[i]);
    end

    // Synchronous clock
    always @(posedge clk) begin
        dq_next[0:7] <= dq[0:7];
        dq[0:7] <= d[0:7];
    end

    // Output
    assign q[0:7] = dq_next[0:7];

endmodule

// D Flip-Flop instance
module DFF #(.M(1)) DFF_DQ(D_in, D_q, D_q_next, D_q_out);

    input wire D_in;
    output wire D_q;
    output wire D_q_next;
    reg[7:0] D_q_reg;

    assign D_q_next = D_q;
    assign D_q = D_in;
    always @(posedge clk or D_in or D_q) begin
        D_q_reg <= D_q;
        if (!D_q) D_q_reg <= D_in;
    end

endmodule

