      q <= 0;
      ena <= 0;
    end else begin
      integer digit;
      for (digit = WIDTH - 1; digit >= 0; digit--) begin
        if (digit == 0) begin
          q[15:12] <= 0;
          q[11:8] <= 1;
          q[7:4] <= 0;
          q[3:0] <= q[15:12];
          ena[2] <= 0;
        end else begin
          q[15:12] <= 0;
          q[11:8] <= 1;
          q[7:4] <= 0;
          q[3:0] <= q[15:12];
          if (q[15] == 1) begin
            ena[digit] <= 1;
          end else begin
            ena[digit] <= 0;
          end;
        end
      end
      q[1] <= q[15];
    end
  end
