module TopModule (
    input clk,
    input reset,
    output reg [ena:0] ena,
    output reg [15:0] q
);

    // Initialize the counter state
    reg [3:0] ones = 0;
    reg [3:0] tens = 0;
    reg [3:0] hundreds = 0;
    reg [3:0] thousands = 0;
    reg [3:0] enable = 0;

    // Decode the counter digits and enable signals
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 0;
            tens <= 0;
            hundreds <= 0;
            thousands <= 0;
            enable <= 0;
        end else begin
            if (ena[2]) ones <= ones + 1;
            if (ena[1]) tens <= tens + 1;
            if (ena[0]) hundreds <= hundreds + 1;
            if (ena[3]) thousands <= thousands + 1;

            // Check for overflow for each digit
            if (ones == 9) ones <= 0;
            if (tens == 9) tens <= 0;
            if (hundreds == 9) hundreds <= 0;
            if (thousands == 9) thousands <= 0;

            // Enable signals for each upper digit
            enable[2] = ones == 9;
            enable[1] = tens == 9;
            enable[0] = hundreds == 9;
        end
    end

    // Output the counter state in BCD format
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 0;
        end else begin
            q[3:0] <= ones;
            q[7:4] <= tens;
            q[11:8] <= hundreds;
            q[15:12] <= thousands;
        end
    end

endmodule

