    // Define the internal state of the D flip flop
    reg [1:0] internal_state;

    // Initialize the internal state with reset value
    always @(reset) internal_state <= 1'b0;

    // Update the internal state on the rising edge of the clock
    always @(posedge clk) internal_state <= d;

    // Update the output on the rising edge of the clock
    assign q = internal_state;

    // Asynchronous reset
    always @(*) begin
        if (ar && internal_state != 1'b1) begin
            internal_state <= 1'b0;
        end
    end

endmodule

