module TopModule(
    input  [255:0] in,
    output [7:0] out
);

    // Initialize counters for 0s and 1s
    reg [7:0] zeros;
    reg [7:0] ones;
    reg carry;

    // Initialize counters with all 0s
    assign zeros = 8'0;
    assign ones = 8'0;

    // Count 0s and 1s in each bit of the input vector
    always @(posedge posedge) begin
        zeros = zeros;
        ones = ones;
        carry = 0;
        for (int i = 0; i < 8; i++) begin
            zeros[i] = in[i] == 0;
            ones[i] = in[i] == 1;
        end
    end

    // Update the counters based on the carry-in bit
    always @(posedge posedge) begin
        // Count the total number of 1s in the input vector
        for (int i = 0; i < 7; i++) begin
            if (ones[i] && zeros[i+1] == 0) begin
                carry = 1;
            end
        end
        if (ones[7] && carry == 1) begin
            ones[7] = 0;
            carry = 1;
        end
        // Clear the carry-out bit
        out = ones;
        ones[7] = carry;
        zeros[7] = ~ones[7]; // toggle the least significant bit of the zeros counter
    end

endmodule

