    reg [1:0] state = 2'b00;

    always @(posedge clk) begin
        if (state == 2'b00) begin
            if (j == 0 && k == 0) begin
                state <= 2'b00;
            end else if (j == 0 && k == 1) begin
                state <= 2'b01;
            end else if (j == 1 && k == 0) begin
                state <= 2'b10;
            end else if (j == 1 && k == 1) begin
                Q <= ~Qold;
                state <= 2'b01;
            end
        end else if (state == 2'b01) begin
            if (j == 0 && k == 1) begin
                state <= 2'b00;
                Q <= 2'b10;
            end else if (j == 1 && k == 1) begin
                state <= 2'b10;
                Q <= 2'b10;
            end
        end else if (state == 2'b10) begin
            if (j == 1 && k == 0) begin
                state <= 2'b00;
                Q <= 2'b00;
            end
        end else if (state == 2'b01) begin
            state <= 2'b10;
            Q <= 2'b10;
        end
    end

    always @(negedge clk) begin
        if (state == 2'b10) begin
            Qold <= Q;
        end
    end

    assign Q = Qold;

endmodule

