module TopModule (
    input  wire in,
    input  wire state,
    output reg next_state,
    output reg out
);

// Define the state transition table
reg [3:0] state_table [4:0] = {
    {4'b0001}, {4'b0010}, {4'b0100}, {4'b1000}
};

// Define the output logic
always @(posedge in or posedge state) begin
    if (in == 1'b1) begin
        // Handle state transition when input is 1
        case (state)
            state_table[state][0]: next_state = {state_table[state][0], in};
            state_table[state][1]: next_state = {state_table[state][1], in};
            default: next_state = state_table[state][0]; // Default to the same state if input is invalid
        endcase
    end
    else begin
        // Handle state transition when input is 0
        case (state)
            state_table[state][0]: next_state = {state_table[state][0], 0};
            state_table[state][1]: next_state = {state_table[state][1], 0};
            default: next_state = state_table[state][0]; // Default to the same state if input is invalid
        endcase
    end
end

endmodule

