module TopModule(a, b, out);
    // XNOR gate implementation
    // XNOR gate is a logical operation that performs a bitwise exclusive or
    // on two input values. The output of an XNOR gate is 1 only when both
    // inputs are 0. This can be implemented using an XOR gate and an AND gate.
    // The XOR gate produces an output of 1 when the inputs are different.
    // The AND gate produces an output of 1 only when both inputs are 1.

    wire xnor;
    wire x, y;

    // Split the input signal into two separate wires
    assign x = a;
    assign y = b;

    // XOR gate to find the difference between the two inputs
    assign xnor = x ^ y;

    // AND gate to ensure that the output is 1 only when both inputs are 0
    assign out = xnor & ~xnor;

endmodule

