module TopModule(mode_in, too_cold_in, too_hot_in, fan_on_in, heater_out, aircon_out, fan_out);

    output heater;
    output aircon;
    output fan;
    input mode_in;
    input too_cold_in;
    input too_hot_in;
    input fan_on_in;

    reg [0:1] mode;
    reg [0:1] heater_status;
    reg [0:1] aircon_status;
    reg [0:1] fan_status;

    initial mode = 0; // default mode is cooling

    always @(posedge mode_in) begin
        mode = mode_in;
        heater_status = 0; // reset heater to off
        aircon_status = 0; // reset aircon to off
        fan_status = 0; // reset fan to off
    end

    always @(posedge mode_in) begin
        if (mode == 1) begin // heating mode
            if (too_cold_in == 1) begin // heater is too cold
                heater_status = 1; // turn heater on
            end else begin // heater is not too cold
                heater_status = 0; // turn heater off
            end
        end else begin // cooling mode
            if (too_hot_in == 1) begin // aircon is too hot
                aircon_status = 1; // turn aircon on
            end else begin // aircon is not too hot
                aircon_status = 0; // turn aircon off
            end
        end
    end

    always @(posedge heater_status) begin
        heater = heater_status;
        fan_status = 1; // turn fan on
    end

    always @(posedge aircon_status) begin
        aircon = aircon_status;
        fan_status = 1; // turn fan on
    end

    always @(posedge fan_status) begin
        fan = fan_status;
    end

    always @(posedge fan_on_in) begin
        fan_status = 1; // turn fan on
    end

endmodule

