module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

reg [2:0] ena_reg;
reg [15:0] q_reg;
reg [1:0] carry;
reg [3:0] tens;
reg [3:0] ones;

always_comb begin
    if (reset) begin
        ena_reg = 3'b000;
        q_reg = 16'd0;
        carry = 1'b0;
        tens = 4'b0000;
        ones = 4'b0000;
    end else begin
        if (~carry & ones & ones == 3'b111)
            ones = 4'b0000;
        else if (ones == 3'b111)
            ones = 1'b1;
        else if (~ones & tens & tens == 3'b111)
            tens = 4'b0000;
        else if (tens == 3'b111)
            tens = 1'b1;
        else if (~tens & ones)
            tens = tens + 1;
        else if (ones)
            ones = ones + 1;

        if (tens == 3'b111)
            tens = 4'b0000;
        else if (tens == 3'b110)
            tens = tens + 1;
        else if (tens > 3'b110)
            tens = 4'b0000;

        if (ones == 3'b111)
            ones = 4'b0000;
        else if (ones == 3'b110)
            ones = ones + 1;
        else if (ones > 3'b110)
            ones = 4'b0000;
    end

    ena_reg = 3'b0;
    if (~carry & tens & tens == 3'b111)
        ena_reg = ena_reg | 3'b1;
    else if (tens == 3'b111)
        ena_reg = ena_reg | 3'b1;
    else if (~tens & ones & ones == 3'b111)
        ena_reg = ena_reg | 3'b1;
    else if (ones == 3'b111)
        ena_reg = ena_reg | 3'b1;
    if (tens > 3'b110)
        ena_reg = ena_reg | 3'b1;
    if (ones > 3'b110)
        ena_reg = ena_reg | 3'b1;
    if (~carry & tens & tens == 3'b111 & ones > 3'b110)
        ena_reg = ena_reg | 3'b1;
    if (~carry & ones & ones == 3'b111 & tens > 3'b110)
        ena_reg = ena_reg | 3'b1;

    end
end

assign ena = ena_reg;
assign q = q_reg;

always_ff @(posedge clk) begin
    if (reset) begin
        q_reg <= 16'd0;
        carry <= 1'b0;
    end else begin
        q_reg <= tens * 4'd10 + ones;
        carry <= tens;
    end
end

endmodule

