module TopModule(mode, too_cold, too_hot, fan_on, heater, aircon, fan);

    parameter HEATING_MODE = 1;
    parameter COOLING_MODE = 0;

    reg[1:0] mode_next;
    reg[1:0] too_cold_next;
    reg[1:0] too_hot_next;
    reg fan_next;
    reg heater_next;
    reg aircon_next;

    always_comb
    begin
        case (mode)
            HEATING_MODE:
                mode_next = mode;
                too_cold_next = too_cold;
                too_hot_next = 0;
                heater_next = too_cold;
                aircon_next = 0;
                fan_next = 1;
                break
            COOLING_MODE:
                mode_next = mode;
                too_cold_next = 0;
                too_hot_next = too_hot;
                heater_next = 0;
                aircon_next = too_hot;
                fan_next = 1;
                break
            default:
                mode_next = mode;
                too_cold_next = too_cold;
                too_hot_next = 0;
                heater_next = 0;
                aircon_next = 0;
                fan_next = 0;
                break
        endcase
    end

    always_seq
    begin
        if (mode_next[1] == 1 && mode_next[0] == 0) begin
            heater <= 0;
            aircon <= 0;
        end
        else begin
            heater <= mode_next[0];
            aircon <= mode_next[1];
        end

        if (too_hot_next[1] == 1) begin
            aircon <= 1;
        end
        else begin
            aircon <= 0;
        end

        if (mode_next[1] == 1 && mode_next[0] == 0) begin
            fan <= 0;
        end
        else begin
            fan <= mode_next[1];
        end

        if (fan_on) begin
            fan <= 1;
        end
    end

    always_comb
    begin
        if (mode == HEATING_MODE && heater == 1) begin
            heater <= 1;
        end
        else if (mode == COOLING_MODE && aircon == 1) begin
            heater <= 1;
        end
        else begin
            heater <= 0;
        end
    end

    always_comb
    begin
        if (mode == HEATING_MODE) begin
            aircon <= 0;
        end
        else begin
            aircon <= 1;
        end
    end

    always_comb
    begin
        if (mode == HEATING_MODE && too_cold == 1) begin
            fan <= 1;
        end
        else if (mode == COOLING_MODE && too_hot == 1) begin
            fan <= 1;
        end
        else begin
            fan <= 0;
        end
    end

    always_comb
    begin
        if (heater == 1 || aircon == 1) begin
            fan <= 1;
        end
        else begin
            fan <= 0;
        end
    end

    always_comb
    begin
        if (fan_on) begin
            fan <= 1;
        end
        else begin
            fan <= 0;
        end
    end

endmodule

