    reg [1:0] shiftRegState;

    // Load state variable
    reg loadState;

    initial begin
        shift Reg = 0;
        counter = 0;
        shiftRegState = 0;
        loadState = 0;
    end

    always @(posedge clk) begin
        counter <= counter + 1;
        if (counter == 4'b1000) begin
            counter <= 4'b0000;
            loadState <= 0;
        end
    end

    always @(posedge shiftRegState) begin
        if (loadState == 1) begin
            shift Reg[3:2] <= R[1:0];
            shift Reg[4] <= R;
            shiftRegState <= shiftRegState + 1;
        end else if (shiftRegState == 1'b1 && loadState == 0) begin
            shift Reg[3:2] <= w[1:0];
            shift Reg[4] <= w;
            shiftRegState <= 2'b00;
        end
    end

    always @(posedge L) begin
        loadState <= 1;
    end

    always_comb begin
        Q <= shift Reg[3];
    end

