module TopModule(
    input  [255:0] in,
    output  [7:0] out
);

    // Shared variables
    logic [1:0] pop_count;

    // Pop count function
    task PopCount
    begin
        pop_count <= 0;
        for (int i = 0; i < 8; i++) begin
            pop_count <= pop_count + ((in[(2*i+7):((2*i+7) + 1)]) && !(in[((2*i+6):((2*i+6) + 1))]));
        end
    endtask

    // Output pop count
    always @(out)
    begin
        out <= pop_count;
    end

    // Population count main loop
    reg [255:0] carry;
    for (int i = 0; i < 255; i++) begin
        carry <= carry + in[i];

        if (carry >= 2) begin
            pop_count <= pop_count + 1;
            carry[1:0] <= 1;
            carry[255:254] <= carry[255:254] - 1;
        end else if (carry >= 1) begin
            pop_count <= pop_count + 1;
            carry[0] <= 1;
            carry[254:253] <= carry[254:253] - 1;
        end else if (carry > 0) begin
            pop_count <= pop_count + 1;
            carry <= carry - 1;
        end
    end

    initial
    begin
        pop_count <= 0;
        carry <= 0;
    end
endmodule

