module TopModule (
    input  wire in,
    input  wire state,
    output reg next_state,
    output reg out
);

// Define the state transition table
reg [3:0] state_table [4:0] = {
    {4'b0001}, {4'b0010}, {4'b0100}, {4'b1000}
};

// Define the output logic table
reg [1:0] output_table [4:0] = {
    {1'b00}, {1'b01}, {1'b00}, {1'b01}
};

always @(*) begin
    // Get the current state and the input
    reg [3:0] current_state = state_table[state];
    reg [0:0] in_data = in;

    // Perform the state transition
    case (current_state)
        4'b0001: begin
            if (in_data == 0) begin
                next_state = state_table[0];
            end else begin
                next_state = state_table[1];
            end
        end
        4'b0010: begin
            if (in_data == 0) begin
                next_state = state_table[1];
            end else begin
                next_state = state_table[2];
            end
        end
        4'b0100: begin
            if (in_data == 0) begin
                next_state = state_table[2];
            end else begin
                next_state = state_table[3];
            end
        end
        4'b1000: begin
            if (in_data == 0) begin
                next_state = state_table[3];
            end else begin
                next_state = state_table[0];
            end
        end
    endcase

    // Get the output from the state transition table
    out = output_table[current_state];
end

endmodule

