    reg [15:0] counter;
    reg [8:0] temp_counter;
    reg [8:0] temp_out;

    always @(posedge clk) // assuming a clock signal is available
        in_reg <= in;
        counter <= counter + 1;
        temp_counter <= counter;

    always @(posedge clk) // using a register to delay the clock
    begin
        if (temp_counter == 0) // if the counter overflows
            counter <= 256;
        if (in_reg[7:0] == temp_counter) // if the most significant 8 bits of the counter match the input
            temp_out <= $count_ones(temp_counter);
        // This pattern will repeat for the remaining values of in_reg[7:0] that match the counter
        else if (in_reg[7:0] > temp_counter)
            temp_out <= 0;
    end

    assign out = temp_out[7:0];

