module TopModule(clk, reset, ena, q);

    reg [16:0] counter;
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;
    reg [1:0] enable_high;
    reg [1:0] enable_mid;
    reg [1:0] enable_low;

    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            ones <= 0;
            tens <= 0;
            hundreds <= 0;
            thousands <= 0;
            enable_high <= 0;
            enable_mid <= 0;
            enable_low <= 0;
        end
        else begin
            counter <= counter + 1;
            ones <= (counter & 0x07);
            tens <= (counter & 0x70) >> 4;
            hundreds <= (counter & 0xF0) >> 8;
            thousands <= (counter & 0xF000) >> 12;

            if (counter == 0xF) begin
                ones <= 0;
                tens <= 0;
                hundreds <= 0;
                thousands <= 0;
                counter <= 0;
            end

            enable_high <= (ones == 3);
            enable_mid <= (tens == 3);
            enable_low <= (ones == 0 || (ones == 1 && tens == 0) || (ones == 2 && tens == 1));
        end
    end

    assign q[7:4] = thousands;
    assign q[11:8] = hundreds;
    assign q[15:12] = tens;
    assign q[1:0] = ones;
    assign ena = (enable_high | enable_mid | enable_low);

endmodule

