    parameter [3:0] A = 4'b0001;
    parameter [3:0] B = 4'b0010;
    parameter [3:0] C = 4'b0100;
    parameter [3:0] D = 4'b1000;

    // State transition logic
    always_comb begin
        case(state)
            A:      next_state = (in == 0) ? A : B;
            B:      next_state = (in == 1) ? C : B;
            C:      next_state = (in == 0) ? A : D;
