module TopModule(clk, resetn, byteena, d, q);

    reg [15:0] q[16];
    reg [1:0] byteena_enable[16];

    always_ff @(posedge clk) begin
        if (~resetn) begin
            byteena_enable <= 2'b00;
        end else begin
            byteena_enable <= byteena;
        end

        for (int i = 0; i < 16; i++) begin
            if (byteena_enable[i] == 2'b01) begin
                q[i*8 + 7] <= d[i*8 + 7];
                q[i*8 + 8] <= d[i*8 + 8];
            end else if (byteena_enable[i] == 2'b10) begin
                q[i*8 + 0] <= d[i*8 + 0];
                q[i*8 + 1] <= d[i*8 + 1];
            end else begin
                q[i*8 + 0] <= q[i*8 + 0];
                q[i*8 + 1] <= q[i*8 + 1];
                q[i*8 + 7] <= q[i*8 + 7];
                q[i*8 + 8] <= q[i*8 + 8];
            end
        end
    end

    assign q[16] = q[0];

endmodule

