    if (reset) begin
        count <= 0;
        enable <= 3'b111;
    end else begin
        if (count < 9) begin
            count <= count + 1;
            enable <= 3'b111;
        end else begin
            count <= 0;
            enable <= 3'b000;
        end
    end
end

