module TopModule(
    input  in,
    input  [3:0] state, // 4-bit state variable
    output  [3:0] next_state, // 4-bit next state variable
    output  out
);

    // One-hot state encoding
    localparam A = 4'd1;
    localparam B = 4'd2;
    localparam C = 4'd4;
    localparam D = 4'd8;

    always_comb begin
        // State transition logic
        case(state)
            4'd0: next_state = A;
            4'd1: next_state = B;
            4'd2: next_state = C;
            4'd3: next_state = D;
            default: next_state = state;
        endcase

        // Output logic (since output is always high when in D state)
        case(next_state)
            A: out = 0;
            B: out = 0;
            C: out = 0;
            D: out = 1;
        endcase
    end

endmodule

