module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

// Register file for BCD counter
reg [7:0] q_counter = 0;
reg [1:0] q Enable = 2'b00;

// State machine for BCD counter
always @(posedge clk) begin
    if (reset) begin
        q_counter <= 8'b0000;
    end else begin
        if (q[1] == '1' && q[2] == '1') begin
            // Increment count by 1
            q_counter <= q_counter + 1;
        end else if (q[1] == '1') begin
            // Increment count by 100
            q_counter <= q_counter + 100;
        end else if (q[2] == '1') begin
            // Increment count by 10
            q_counter <= q_counter + 10;
        end
        if (q_counter >= 16) begin
            q_counter <= 8'b0000;
        end
        if (q[0] == '1') begin
            // Increment ones place
            q_counter <= q_counter + 1;
        end
        if (q[0] == '0' && q[1] == '0') begin
            // Reset ones place
            q_counter <= 8'b0000;
        end
    end
end

// Calculate BCD digits
assign q[3:0] = q_counter % 10;
q_counter <= q_counter / 10;

// Calculate tens, hundreds digits
assign q[7:4] = q_counter / 100 % 10;
q_counter <= q_counter / 100;

// Calculate thousands digit
assign q[11:8] = q_counter / 1000 % 10;
q_counter <= q_counter / 1000;

// Enable signal calculation
assign ena = {(q[0] == '1', q[1] == '1', q[2] == '1'});

endmodule

