module TopModule(clk, arereset, d, q);

    reg [7:0] q[7:0]; // 8-bit wide register

    // Asynchronous active-high reset
    reg [7:0] q_prev;
    reg [7:0] q_next;
    wire q_prev_older;
    wire q_prev_next;
    wire q_next_older;
    wire q_next_next;

    // Initialize q_prev with all zeros
    assign q_prev_older = 8'd0;

    // Compute q_next using q_prev, d, and clk
    always_ff @(posedge clk) begin
        // Update q_prev with the old value of q_next
        assign q_prev_next = q_prev_older;
        q_prev_older <= q_prev_next;

        // Compute q_next
        q_next_next <= q_prev_next;
        q_next <= q_next_next;

        // Update q with q_next
        assign q_next_older = q_next;
        q <= q_next_older;

    end : always_ff

    // Initialize the first DFF with q_prev_older
    assign q_prev_next = q_prev_older;

    // Initialize the remaining DFFs with q_prev
    for (int i = 0; i < 7; i++) begin
        assign q_prev_next[i] = q_prev[i];
    end

    // Input port
    assign d[0] = d[0];

    // Assign q to the output port
    assign q[7:0] = q_next[7:0];

    // Asynchronous reset
    assign q_next_next[0] = 8'd0;
    for (int i = 1; i < 8; i++) begin
        assign q_next_next[i] = q_prev_next[i-1];
    end

endmodule

