module TopModule(
    input  [1023:0] in,
    input  [7:0] sel,
    output [3:0] out
);

    // 4-bit multiplexer configuration
    parameter WIDTH = 4;
    parameter NUM Selbits = $log2(256);
    parameter NUM_inputs = WIDTH * 256;

    // Calculate the width of the packed input vector
    parameter input_width = WIDTH * NUM_inputs;

    // Create the packed input vector
    wire [input_width-1:0] packed_in;

    assign packed_in = in[0:input_width-1];

    // Calculate the start index for each sel value
    reg [input_width-1:0] start_idx;
    start_idx = {(sel == 8'b0) ? 0 : (sel == 8'b1) ? WIDTH : (sel == 8'b2) ? WIDTH*2 : (sel == 8'b3) ? WIDTH*2 + WIDTH : 0};

    // Create the multiplexer
    wire [WIDTH-1:0] temp;
    assign temp = packed_in[start_idx:start_idx + WIDTH - 1];

    assign out = temp[3:0];

endmodule

