    input R,
    input E,
    input L,
    output Q
);

// Define the combinational logic
always_comb begin
    // Initialize the output
    Q = 0;

    // If E is asserted, copy the previous input w
    if (E) begin
        Q = w;
    // If R is asserted, load the value
    else if (R) begin
        Q = R;
    // If L is asserted, propagate the value
    else if (L) begin
        Q = w;
    end
end

