    input  logic  c,         // 1-bit input
    input  logic  d,         // 1-bit input
    input  logic  e,         // 1-bit input
    output logic [24:0] out  // 25-bit output
);

    always_comb begin
        // Generate all 25 pairwise comparisons
        for (int i = 0; i < 5; i++) begin
            for (int j = 0; j < 5; j++) begin
                // Create the output index for this pair
                int idx = j * 5 + i;
                // out[idx] will hold the result of ~a ^ b
                if (i == j) begin
                    // If we're comparing a to itself, the output will be 0
                    out[idx] = ~a & ~b & ~c & ~d & ~e;
                end else begin
                    // For all other comparisons, ~a ^ b will always be 1
                    out[idx] = 1;
                end
            end
        end
    end

endmodule

