module TopModule (
    input clk,
    input w,
    input R,
    input E,
    input L,
    output Q
);

    reg [7:0] data; // Assuming a 8-bit shift register
    reg Q;         // Output for the current data bit

    always @(posedge clk) begin
        if (E) begin
            // Clear the shift register
            data <= 8'b00000000;
        end else if (R) begin
            // Load data from w onto the shift register
            data <= w;
        end else if (L) begin
            // Load the data bit from the previous register onto the current shift register
            data <= data << 1;
            if (data == 8'b00000000) begin
                data <= 8'b00000000;
            end
        end else if (data != 8'b00000000) begin
            // Shift the data to the left by one bit
            data <= data << 1;
            Q <= data[0]; // Output the current data bit
        end else begin
            Q <= data[0]; // Output the current data bit
        end
    end

