module TopModule(
    input  clk,
    input  reset,
    output  [2:0] ena,  // enable for upper three digits
    output  [15:0] q    // 4-digit BCD counter
);

reg  [2:0] ena_prev;
reg  [15:0] q_prev;
reg  [3:0] cnt[4:0];

always @(posedge clk) begin
    if (reset) begin
        ena_prev <= 0;
        q_prev  <= 0;
        for (int i = 0; i < 4; i++) begin
            cnt[i] <= 0;
        end
    end else begin
        ena_prev <= ena;
        for (int i = 0; i < 4; i++) begin
            cnt[i] <= cnt[i] + 1;
        end
        if (cnt[4] == 0) begin
            cnt[4] <= 4;
            for (int i = 0; i < 4; i++) begin
                cnt[i] <= 0;
            end
        end else begin
            cnt[4] <= cnt[4] - 1;
        end

        // encode BCD
        q[3] <= cnt[4] % 10;
        q[2] <= cnt[3] % 10;
        q[1] <= cnt[2] % 10;
        q[0] <= cnt[1] % 10;

        // calculate tens digits
        q[7] <= (cnt[4] / 10) % 10;
        q[6] <= (cnt[3] / 10) % 10;
        q[5] <= (cnt[2] / 10) % 10;
        q[4] <= (cnt[1] / 10) % 10;

        // enable signals
        for (int i = 0; i < 3; i++) begin
            ena[i] <= ena_prev && cnt[4-i] == 0;
        end
    end
end

assign q[15:8] = q[7:4];
assign q[11:5] = q[6:4];
assign q[1:0] = q[4:3];

endmodule

