module TopModule(clk, w, R, E, L, Q);

    // Internal signals
    reg [1:0] prev_data;
    reg [1:0] data_to_shift;
    reg Q_next;

    // Clock process
    always @(posedge clk) begin
        if (E) begin
            // Load new value
            prev_data <= R;
            Q_next <= prev_data[0];
        end else if (L) begin
            // Shift value
            data_to_shift <= prev_data;
            if (w) begin
                Q_next <= data_to_shift;
            end else begin
                Q_next <= 1'b0;
            end
        end else begin
            // No change
            Q_next <= prev_data[0];
        end
    end

    // Output assignment
    assign Q = Q_next;

