module TopModule(
    input  a,        // bit
    input  b,        // bit
    input  c,        // bit
    input  d,        // bit
    output out      // bit
);

// State variables
reg [1:0] state = 2'b00; // 2-bit state variable

// Karnaugh map
reg [2:0] kmap_value;
reg [2:0] kmap_out;

assign kmap_value = {a, b, c};
assign kmap_out = kmap_value[2:0];

// Next state logic
always @(*)
begin
    // State transitions
    if (state == 2'b00 && kmap_out == 2'b01) state = 2'b01;
    if (state == 2'b00 && kmap_out == 2'b10) state = 2'b11;
    if (state == 2'b01 && kmap_out == 2'b00) state = 2'b00;
    if (state == 2'b01 && kmap_out == 2'b11) state = 2'b11;
    if (state == 2'b11 && kmap_out == 2'b00) state = 2'b00;
    if (state == 2'b11 && kmap_out == 2'b01) state = 2'b11;
    if (state == 2'b10 && kmap_out == 2'b00) state = 2'b10;
    if (state == 2'b10 && kmap_out == 2'b11) state = 2'b11;

    // Output assignment
    if (state == 2'b00) out <= 1'b0;
    else if (state == 2'b01) out <= 1'b1;
    else if (state == 2'b11) out <= 1'b1;
    else if (state == 2'b10) out <= 1'b0;
end

endmodule

