                if ((byteena & 2'd1) == 2'd1) begin
                    q[i] <= d[7 + 8 * i];
                end else if ((byteena & 2'd0) == 2'd0) begin
                    q[i] <= d[15 + 8 * i];
                end else begin
                    q[i] <= w[i];
                end
            end
        end
    end

    always @(posedge clk) begin
        for (int i = 0; i < 16; i++) begin
            w[i] <= q[i];
        end
    end

