module TopModule(a, b, c, d, out);

    // Karnaugh map implementation
    always_comb begin
        // 00: d = 1, c = 0, b = 0, a = 0
        if (a == 0 && b == 0) begin
            if (c == 0) begin
                if (d == 0) out = 1'b0;
                else if (d == 1) out = 1'b1;
            end else if (c == 1) begin
                if (d == 0) out = 1'b1;
                else if (d == 1) out = 1'b0;
            end
        end

        // 01: d = 1, c = 1, b = 0, a = 0
        else if (a == 0 && b == 1) begin
            if (c == 0) begin
                if (d == 0) out = 1'b1;
                else if (d == 1) out = 1'b0;
            end else if (c == 1) begin
                if (d == 0) out = 1'b0;
                else if (d == 1) out = 1'b1;
            end
        end

        // 11: d = 0, c = 0, b = 1, a = 0
        else if (a == 0 && b == 1) begin
            if (c == 0) begin
                if (d == 0) out = 1'b0;
                else if (d == 1) out = 1'b1;
            end else if (c == 1) begin
                if (d == 0) out = 1'b1;
                else if (d == 1) out = 1'b0;
            end
        end

        // 10: d = 0, c = 1, b = 0, a = 1
        else if (a == 1 && b == 0) begin
            if (c == 0) begin
                if (d == 0) out = 1'b1;
                else if (d == 1) out = 1'b0;
            end else if (c == 1) begin
                if (d == 0) out = 1'b0;
                else if (d == 1) out = 1'b1;
            end
        end
    end

endmodule

