module TopModule(
    input  in,
    input  [3:0] state,
    output  [3:0] next_state,
    output  out
);

    // One-hot state encoding
    assign state_encoded = {out1 : out2, out3, out4 : out5};

    // State transition table
    always_comb begin
        case(state)
            4'b0000 : out1 = 1'b0, out2 = 1'b0, out3 = 1'b0, out4 = 1'b0;
            4'b0001 : out1 = 1'b1, out2 = 1'b0, out3 = 1'b0, out4 = 1'b0;
            4'b0010 : out1 = 1'b0, out2 = 1'b1, out3 = 1'b0, out4 = 1'b0;
            4'b0100 : out1 = 1'b0, out2 = 1'b0, out3 = 1'b1, out4 = 1'b0;
            4'b1000 : out1 = 1'b0, out2 = 1'b0, out3 = 1'b0, out4 = 1'b1;
            default   : #error("Invalid state")
        endcase
    end

    // Next state logic
    always_comb begin
        case(state)
            4'b0000 : next_state = 4'b0000;
            4'b0001 : next_state = 4'b0001;
            4'b0010 : next_state = 4'b0100;
            4'b0100 : next_state = 4'b0010;
            4'b1000 : next_state = 4'b1000;
            default   : #error("Invalid state")
        endcase
    end

    // Output logic
    always_comb begin
        case(state)
            4'b0000 : out = 1'b0;
            4'b0001 : out = 1'b1;
            4'b0010 : out = 1'b0;
            4'b0100 : out = 1'b0;
            4'b1000 : out = 1'b1;
            default   : #error("Invalid state")
        endcase
    end

endmodule

