module TopModule(
    input a, b, c, d,
    output out
);

// Using the Karnaugh map to implement the circuit
// The output is 1 only when the inputs are (ab) or (cd) in the following order:
// ab: 00, 01, 11, 10
// cd: 00, 01, 11, 10
// The output is 0 when cd is 10

// Calculate ab
localparam ab_00 = 1;
localparam ab_01 = 1;
localparam ab_11 = 1;
localparam ab_10 = 1;
localparam ab_1x = 1; // Use the XOR gate to get the 1x value
localparam ab_0x = 1; // Use the XOR gate to get the 0x value

// Calculate cd
localparam cd_00 = 1;
localparam cd_01 = 1;
localparam cd_11 = 1;
localparam cd_10 = 0;

// Calculate ab | cd
localparam ab_cd = ab_01 | cd_01;

// Calculate the output
localparam out_00 = ab_cd | cd_00;
localparam out_01 = ab_cd | cd_01;
localparam out_11 = ab_cd | cd_11;
localparam out_10 = ab_01 | cd_10;
localparam out_x = ab_1x | cd_11;
localparam out_0x = ab_0x | cd_10;

// Select the output based on the inputs
assign out = ab_cd ? out_01 : (ab_cd & cd_10) ? out_10 : (ab_cd & cd_11) ? out_11 : ab_cd & !cd_10 ? out_00 : ab_cd & !cd_11 ? out_01 : (ab_cd & !cd_10 & !cd_11) ? out_x : (ab_cd & !cd_10 & !cd_11) ? out_0x : 0;

endmodule

