module TopModule(
    input mode,
    input too_cold,
    input too_hot,
    input fan_on,
    output heater,
    output aircon,
    output fan
);

// State variables
reg [1:0]  mode_state = 1'b0; // Initial mode is cooling
reg [1:0]  heater_state = 1'b0; // Initial heater state is off
reg [1:0]  aircon_state = 1'b0; // Initial aircon state is off

// Define states
typedef enum reg [1:0] {
    COOLING,
    HEATING
} States;

// Function to update mode state
States update_mode_state(
    input mode,
    input too_cold,
    input too_hot
) {
    if (mode == 1) { // Mode changed to heating
        return COOLING;
    } else if (mode == 0) { // Mode changed to cooling
        return HEATING;
    } else { // Mode remaining the same
        return mode_state;
    }
}

// Function to update heater state
States update_heater_state(
    input too_cold
) {
    if (too_cold == 1) { // Too cold, turn on heater
        return HEATING;
    } else { // Too cold, turn off heater
        return COOLING;
    }
}

// Function to update aircon state
States update_aircon_state(
    input too_hot
) {
    if (too_hot == 1) { // Too hot, turn on aircon
        return COOLING;
    } else { // Too hot, turn off aircon
        return COOLING;
    }
}

// Function to update fan state
States update_fan_state(
    input fan_on
) {
    if (fan_on == 1) { // Fan turned on
        return COOLING;
    } else if (heater_state == 1'b1) { // Heater turned on, fan also turned on
        return COOLING;
    } else if (aircon_state == 1'b1) { // Aircon turned on, fan also turned on
        return COOLING;
    } else { // Fan turned off
        return COOLING;
    }
}

// Main logic
always @({mode, too_cold, too_hot, fan_on}) begin
    mode_state = update_mode_state(mode, too_cold, too_hot);
    heater_state = update_heater_state(too_cold);
    aircon_state = update_aircon_state(too_hot);
    fan_state = update_fan_state(fan_on);

    if (mode_state == COOLING) {
        heater_state = 1'b0;
        aircon_state = 1'b1;
    } else {
        heater_state = 1'b1;
        aircon_state = 1'b0;
    }
end

// Assign outputs
assign heater = heater_state;
assign aircon = aircon_state;
assign fan = fan_state;

endmodule

