module TopModule(
    input  [1023:0] in,
    input  [7:0] sel,
    output [3:0] out
);

    reg [7:0] sel_reg;
    reg [11:8] sel_reg_2;
    reg [15:12] sel_reg_3;
    reg [19:16] sel_reg_4;
    reg [23:20] sel_reg_5;
    reg [27:24] sel_reg_6;
    reg [31:28] sel_reg_7;

    // Calculate the offset for the 256-to-1 multiplexer
    wire offset = (sel_reg[0:3] == sel[0:4]) ? 0 : (sel_reg[4:7] == sel[1:4]) ? 8 : (sel_reg[8:11] == sel[2:4]) ? 16 : (sel_reg[12:15] == sel[3:4]) ? 24 : (sel_reg[16:19] == sel[4:5]) ? 32 : (sel_reg[20:23] == sel[5:5]) ? 40 : (sel_reg[24:27] == sel[6:6]) ? 48 : (sel_reg[28:31] == sel[7:7]) ? 56 : 0;

    // Calculate the start bit of the selected 4-bit word
    wire start = offset + (sel_reg[0:3] == sel[0:4]) ? 0 : (sel_reg[4:7] == sel[1:4]) ? 4 : (sel_reg[8:11] == sel[2:4]) ? 8 : (sel_reg[12:15] == sel[3:4]) ? 12 : (sel_reg[16:19] == sel[4:5]) ? 16 : (sel_reg[20:23] == sel[5:5]) ? 20 : (sel_reg[24:27] == sel[6:6]) ? 24 : (sel_reg[28:31] == sel[7:7]) ? 28 : 32;

    // Select the 4-bit word from the 1024-bit input
    assign out = in[start:start+3];

    // Calculate the next offset for the multiplexer
    reg next_offset = (sel_reg[0:3] == sel[0:4]) ? 24 : (sel_reg[4:7] == sel[1:4]) ? 32 : (sel_reg[8:11] == sel[2:4]) ? 40 : (sel_reg[12:15] == sel[3:4]) ? 48 : (sel_reg[16:19] == sel[4:5]) ? 56 : (sel_reg[20:23] == sel[5:5]) ? 64 : (sel_reg[24:27] == sel[6:6]) ? 72 : (sel_reg[28:31] == sel[7:7]) ? 80 : 0;

    // Update the offset and reg values on rising edge of clock
    always @(posedge clk)
        sel_reg <= sel_reg_2;
        sel_reg_2 <= sel_reg_3;
        sel_reg_3 <= sel_reg_4;
        sel_reg_4 <= sel_reg_5;
        sel_reg_5 <= sel_reg_6;
        sel_reg_6 <= sel_reg_7;
        sel_reg_7 <= sel[0:4];

    // Handle asynchronous reset
    always_ff @(posedge reset)
        sel_reg <= 0;
    always_ff @(posedge reset)
        sel_reg_2 <= 0;
    always_ff @(posedge reset)
        sel_reg_3 <= 0;
    always_ff @(posedge reset)
        sel_reg_4 <= 0;
    always_ff @(posedge reset)
        sel_reg_5 <= 0;
    always_ff @(posedge reset)
        sel_reg_6 <= 0;
    always_ff @(posedge reset)
        sel_reg_7 <= 0;

endmodule

