module TopModule(
    input clk,
    input areset,
    input [7:0] d,
    output [7:0] q
);

// Initialize 8 D flip-flops with active high asynchronous reset
reg [7:0] q[7:0];

always_comb begin
    // Initialize all q[7:0] to 0
    q[0] = 0;
    q[1] = 0;
    q[2] = 0;
    q[3] = 0;
    q[4] = 0;
    q[5] = 0;
    q[6] = 0;
    q[7] = 0;
end

always @(posedge clk or negedge areset) begin
    // Assign q[7:0] on each rising edge of clk
    case(areset)
        1: begin
            // Reset to 0
            q[0] = 0;
            q[1] = 0;
            q[2] = 0;
            q[3] = 0;
            q[4] = 0;
            q[5] = 0;
            q[6] = 0;
            q[7] = 0;
        end
        default: begin
            // Update q[7:0] based on d
            q[0] = d[0];
            q[1] = d[1];
            q[2] = d[2];
            q[3] = d[3];
            q[4] = d[4];
            q[5] = d[5];
            q[6] = d[6];
            q[7] = d[7];
        end
    endcase
end

// Output the value of q[7:0]
assign q = {q[7], q[6], q[5], q[4], q[3], q[2], q[1], q[0]};

endmodule

