module TopModule(clk, w, R, E, L, Q);

    // Define the ports
    input clk;
    input w;
    input R;
    input E;
    input L;
    output logic Q;

    // Define the state of the shift register
    logic [1:0] state;

    // Define the current value
    logic [2:0] value;

    // Initialize the value to 0
    initial value = 0;

    // Define the next value based on the current state
    always @(*)
        if (state == 2'b00)
            value = value << 1;
        else if (state == 2'b01)
            value = 2'd1;
        else if (state == 2'b10)
            value = R;
        else if (state == 2'b11)
            value = value << 1;

    // Update the state based on the input E
    always @(*) begin
        if (E) begin
            state = state == 2'b00 ? 2'b01 : state == 2'b01 ? 2'b10 : 2'b11;
        end
    end

    // Update the value when L is asserted
    always @(*) begin
        if (L) begin
            value = R;
        end
    end

    // Update the Q output based on the current state
    always @(*) begin
        if (state == 2'b00)
            Q = value[2];
        else if (state == 2'b01)
            Q = value[0];
        else if (state == 2'b10)
            Q = R;
        else if (state == 2'b11)
            Q = value[2];
    end

endmodule

