reg [7:0] prevShiftRegister = 0; // Previous shift register value

always @(posedge clk) begin
    if (E) begin
        // Handle enabling shift
        if (R) begin
            // Load value R into the shift register
            shiftRegister = R;
        end else begin
            // Load previous shift register value if L is asserted
            if (L) begin
                shiftRegister <= prevShiftRegister;
            end
        end
    end else begin
        // Handle disable shift
