reg [1:0] previous_thermostat_state;

// Heater State
reg heater_on;

// Air Conditioner State
reg aircon_on;

// Fan State
reg fan_on;

// Clock and Reset
always @(posedge posedge clock) begin
    if (reset) begin
        thermostat_state <= 1'b0;
    end else begin
        thermostat_state <= previous_thermostat_state;
    end
end

always @(posedge posedge clock) begin
    if (thermostat_state == 1'b1 && too_cold) begin
        heater_on <= 1'b1;
        aircon_on <= 1'b0;
        fan_on <= 1'b1;
    end else if (thermostat_state == 1'b0 && too_hot) begin
        heater_on <= 1'b0;
        aircon_on <= 1'b1;
        fan_on <= 1'b1;
    end else if (fan_on) begin
        fan_on <= 1'b1;
    end else if (heater_on) begin
        heater_on <= 1'b1;
    end else if (aircon_on) begin
        aircon_on <= 1'b1;
    end else begin
        heater_on <= 1'b0;
        aircon_on <= 1'b0;
        fan_on <= 1'b0;
    end
end

assign heater = heater_on;
assign aircon = aircon_on;
assign fan = fan_on;

