module TopModule (
    input wire mode,
    input wire too_cold,
    input wire too_hot,
    input wire fan_on,
    output reg heater,
    output reg aircon,
    output reg fan
);

    // Define the states of the thermostat
    enum logic [1:0] {HEATING, COOLING, IDLE} state;

    // Define the control signals for the heater, air conditioner, and fan
    logic [1:0] control;

    // Define the logic for the thermostat
    always @(posedge mode or posedge too_cold or posedge too_hot or posedge fan_on) begin
        // Determine the state of the thermostat based on the mode and temperature conditions
        case (mode)
            1'b1: begin
                if (too_cold) begin
                    state <= HEATING;
                    control <= 2'b11; // Turn on heater and fan
                end else begin
                    state <= IDLE;
                    control <= 2'b00; // Turn off heater and fan
                end
            end
            1'b0: begin
                if (too_hot) begin
                    state <= COOLING;
                    control <= 2'b10; // Turn on air conditioner and fan
                end else begin
                    state <= IDLE;
                    control <= 2'b00; // Turn off air conditioner and fan
                end
            end
            default: begin
                state <= IDLE;
                control <= 2'b00; // Turn off heater, air conditioner, and fan
            end
        endcase

        // Apply the control signals to the heater, air conditioner, and fan
        heater <= control[0];
        aircon <= control[1];
        fan <= control[2];
    end

endmodule

