module TopModule(in, state, next_state, out);

// State encoding
typedef enum logic[3:0] state_t {
    A,
    B,
    C,
    D
} state_t;

// State transition table
always_comb begin
    if (state == A) begin
        next_state = (in == 0) ? A : (in == 1) ? B : (B);
    end else if (state == B) begin
        next_state = (in == 0) ? B : (in == 1) ? (in == 0) ? B : (C);
    end else if (state == C) begin
        next_state = (in == 0) ? A : (in == 1) ? D : (B);
    end else if (state == D) begin
        next_state = (in == 0) ? C : (in == 1) ? (in == 0) ? B : (D);
    end
end

// Output logic
always_comb begin
    case (next_state)
        A: out = 0;
        B: out = 0;
        C: out = 1;
        D: out = 1;
    endcase
end

endmodule

