module TopModule (
    input wire in,
    input wire state,
    output wire next_state,
    output wire out
);

// State transition table and output logic equations
always @(posedge clk or posedge rst) begin
    if (rst) begin
        next_state <= A;
        out <= 0;
    end else begin
        // State A
        if (state == A) begin
            if (in == 0) begin
                next_state <= B;
                out <= 0;
            end else if (in == 1) begin
                next_state <= A;
                out <= 0;
            end
        end
        // State B
        else if (state == B) begin
            if (in == 0) begin
                next_state <= C;
                out <= 0;
            end else if (in == 1) begin
                next_state <= B;
                out <= 0;
            end
        end
        // State C
        else if (state == C) begin
            if (in == 0) begin
                next_state <= A;
                out <= 0;
            end else if (in == 1) begin
                next_state <= D;
                out <= 0;
            end
        end
        // State D
        else if (state == D) begin
            if (in == 0) begin
                next_state <= C;
                out <= 0;
            end else if (in == 1) begin
                next_state <= B;
                out <= 1;
            end
        end
    end
end

// State definitions
parameter A = 4'b0001,
        B = 4'b0010,
        C = 4'b0100,
        D = 4'b1000;

endmodule

