    reg [24:0] results [5:0];

    always @(*) begin
        results[0] = ~a ^ a;
        results[1] = ~a ^ b;
        results[2] = ~a ^ c;
        results[3] = ~a ^ d;
        results[4] = ~a ^ e;
        results[5] = ~e ^ d;
        results[6] = ~e ^ e;

        for (integer i = 0; i < 5; i++) begin
            out[i*5 +: 5] = results[i];
        end
    end

endmodule

