module TopModule
(
    // 255-bit input vector
    input [255:0] in,
    // population count of the input vector
    output [7:0] out
);

    // Calculate population count for all bits in the input vector
    reg [255:0] count;
    assign count = in;

    // Calculate population count for each bit in the input vector
    reg [0:0] bit_count;
    assign bit_count[0] = (count[0] & in[1:0]) == 2'b01; // 1's in bit 0
    assign bit_count[1] = (count[1] & in[2:3]) == 2'b01; // 1's in bit 1
    assign bit_count[2] = (count[2] & in[4:5]) == 2'b01; // 1's in bit 2
    assign bit_count[3] = (count[3] & in[8:9]) == 2'b01; // 1's in bit 3
    assign bit_count[4] = (count[4] & in[16:17]) == 2'b01; // 1's in bit 4
    assign bit_count[5] = (count[5] & in[32:33]) == 2'b01; // 1's in bit 5
    assign bit_count[6] = (count[6] & in[64:65]) == 2'b01; // 1's in bit 6
    assign bit_count[7] = (count[7] & in[128:129]) == 2'b01; // 1's in bit 7

    // Shift and sum to calculate the population count
    assign out = $signed(bit_count);
endmodule

