        for (int i = 0; i < 8; i++) begin
            if (prev_in[i] == 0 && in[i] == 1) begin
                edge_in[i] = 1;
            end else if (prev_in[i] == 1 && in[i] == 0) begin
                edge_in[i] = 1;
            end else begin
                edge_in[i] = 0;
            end
        end

        // Combine the edge signals into the anyedge output
        anyedge <= $signed(edge_in);
    end

endmodule

