    input w,
    input R,
    input E,
    input L,
    output Q
);

    reg[7:0] prevData;
    reg[7:0] data;

    always_ff @(posedge clk) begin
        if (E) begin
            prevData <= R;
        end else if (L) begin
            prevData <= data;
        end else begin
            prevData <= prevData;
        end
    end

    always_comb begin
        data[0] <= w;
        for (int i = 1; i < 8; i++) begin
            data[i] <= data[i - 1];
        end
        if (R) begin
            for (int i = 7; i >= 0; i--) begin
                if (data[i] == 1) begin
                    Q <= 1'b1;
                end else begin
                    Q <= 1'b0;
                end
            end
        end else begin
            Q <= Q;
        end
    end

