module TopModule(in, state, next_state, out);
    input in;
    input [3:0] state;
    output [3:0] next_state;
    output [1:0] out;

    always_comb begin
        // Define the one-hot state encoding
        unique case (state)
            4'b0001 : next_state = 4'b0001;
            4'b0010 : next_state = 4'b0010;
            4'b0100 : next_state = 4'b0100;
            4'b1000 : next_state = 4'b1000;
            default : next_state = 4'b0000;
        endcase

        // Compute the output logic equation
        unique case (in)
            0 : out = 1'b0;
            1 : out = !state[0] && state[1];
            default : out = 1'b0;
        endcase
    end
endmodule

