module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

    reg [15:0] count = 0;
    reg [2:0] carry = 0;
    reg [2:0] prev_ena = 0;

    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            carry <= 0;
            prev_ena <= 0;
        end else begin
            count <= count + 1;

            if (count == 4) begin
                count <= 0;
                prev_ena <= 2;
            end else if (count == 3) begin
                count <= 0;
                prev_ena <= 1;
            end else if (count == 2) begin
                count <= 0;
                prev_ena <= 0;
            end

            carry <= (count >= 4) ? 1 : 0;

            // Calculate BCD digits
            q[7] = (count / 10) % 10;
            q[6] = (carry == 0) ? (count / 10) / 10 : 0;
            q[5] = (prev_ena == 2) ? (carry == 0) ? (count / 10) % 10 : 0;
            q[4] = (prev_ena == 1) ? (carry == 0) ? (count / 10) % 10 : 0;
            q[3] = (prev_ena == 0) ? (carry == 0) ? (count / 10) % 10 : 0;
            q[2] = (carry == 1) ? (count / 10) % 10 : 0;
            q[1] = (prev_ena == 2) ? (carry == 0) ? (count / 10) % 10 : 0;
            q[0] = (prev_ena == 1) ? (carry == 0) ? (count / 10) % 10 : 0;

            // Calculate enable signals
            ena <= (prev_ena == 2) ? 2'b11 : (prev_ena == 1) ? 2'b10 : 2'b00;
        end
    end

