module TopModule(clk, w, R, E, L, Q);

    always_comb begin
        // Shift data from w to Q
        assign Q = w;

        // Enable load of value
        assign R = R;

        // Check if L is asserted and E is enabled
        // Load the value R onto the shift register
        assign L = E & L;

        // Shift data from Q to w
        assign w = Q;
    end

    always_pos_edge(clk) begin
        // If load is asserted, shift the data and reset the load
        if (L) begin
            w <= 1;  // Shift data
            R <= 1;  // Load value into shift register
            L <= 0;  // Reset load
        end
    end

endmodule

