module TopModule(clk, reset, q);
    // Input ports
    input clk;
    input reset;

    // Output port
    output reg [3:0] q;

    // Internal counter state (4 bits)
    reg [3:0] counter;

    // Counter increment signal
    reg signed [1:0] increment;

    // Initialize counter to 0
    initial begin
        q <= 0;
        counter <= 0;
        increment <= 0;
    end

    // Synchronous counter increment
    always @(posedge clk) begin
        if (reset) begin
            // Reset counter on active high reset edge
            counter <= 0;
            increment <= 0;
        else begin
            // Increment counter
            if (counter == 15) begin
                // Overflow to 0
                counter <= 0;
                increment <= 1;
            else begin
                // Increment counter by 1
                counter <= counter + increment;
                increment <= 0;
            end
        end
    end

    // Update output
    always @(posedge clk) begin
        q <= counter;
    end
endmodule

