module TopModule(
    input  [255:0] in,  // 255-bit input vector
    output [7:0] out   // 8-bit output
);

    reg [255:1] temp;  // 256-bit temporary storage
    reg [8:0] count;   // 8-bit population count
    reg [255:1] carry; // 256-bit carry
    reg [8:0] carry_out; // 8-bit carry output

    always @(posedge in) begin
        temp[0:0] = in[0:0];
        for (int i = 1; i <= 255; i++) begin
            temp[i:1] = temp[i - 1] | in[i:1];
        end

        count[0:0] = temp[0:0];
        for (int i = 1; i <= 7; i++) begin
            count[i] = temp[i:1] & (~temp[i - 1]);
        end

        for (int i = 0; i <= 7; i++) begin
            carry[i] = count[i] & temp[i];
        end

        carry_out[0:0] = carry[0:0];
        for (int i = 1; i <= 7; i++) begin
            carry_out[i] = carry[i] | carry_out[i - 1];
        end

        out <= carry_out;
    end

endmodule

