    input b,
    input sel_b1,
    input sel_b2,
    output reg out_assign,
    output reg out_always
);

always @(posedge clk or posedge rst) begin
    if (rst) begin
        out_assign <= 1'b0;
        out_always <= 1'b0;
    end else begin
        if (sel_b1 && sel_b2) begin
            out_assign <= b;
            out_always <= b;
        end else begin
            out_assign <= a;
            out_always <= a;
        end
    end
end

reg [1:0] state = 2'b0;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= 2'b0;
    end else begin
        case (state)
            2'b0: state <= 2'b1;
            2'b1: state <= 2'b0;
            default: state <= 2'b0;
        endcase
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        out_assign <= 1'b0;
        out_always <= 1'b0;
    end else begin
        if (state == 2'b1) begin
            out_assign <= b;
            out_always <= b;
        end else begin
            out_assign <= a;
            out_always <= a;
        end
    end
end

endmodule

