module TopModule(
    input a, 
    input b, 
    input c, 
    input d, 
    output out
);

    parameter valid_values = 2;

    reg [valid_values - 1:0] ab;
    reg [valid_values - 1:0] cd;
    reg [valid_values - 1:0] temp;
    reg [valid_values - 1:0] result;
    reg out_val;

    always @(posedge a) begin
        case(ab)
            0: ab = 0;
            1: ab = 1;
            default: $fatal_error("Invalid value for ab");
        endcase
    end

    always @(posedge b) begin
        case(cd)
            0: cd = 0;
            1: cd = 1;
            default: $fatal_error("Invalid value for cd");
        endcase
    end

    assign temp = ab | cd;
    assign out_val = {out, temp[(valid_values - 1):0]};

    always @(*) begin
        if (temp == 3'b001) out_val = out_val | 1;
        else if (temp == 3'b011) out_val = out_val | 1;
        else if (temp == 3'b101) out_val = out_val | 1;
        else if (temp == 3'b110) out_val = out_val | 1;
        else if (temp == 3'b000) out_val = out_val | 0;
        else if (temp == 3'b010) out_val = out_val | 1;
        else if (temp == 3'b110) out_val = out_val | 0;
        else if (temp == 3'b011) out_val = out_val | 0;
        else if (temp == 3'b101) out_val = out_val | 0;
        end

        out = out_val;
    end

endmodule

