module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);

reg [1:0] counter;
reg [1:0] carry;
reg [3:0] ones;
reg [3:0] tens;
reg [3:0] hundreds;
reg [3:0] thousands;
reg [3:0] enable_threes;
reg [3:0] enable_twos;
reg [3:0] enable_ones;

always_ff @(posedge clk) begin
    if (reset) begin
        counter <= 0;
        carry <= 0;
        ones <= 4;
        tens <= 0;
        hundreds <= 0;
        thousands <= 0;
        enable_threes <= 0;
        enable_twos <= 0;
        enable_ones <= 1;
    end else begin
        counter <= counter + 1;
        if (counter == 2) begin
            carry <= 1;
        end else if (counter > 2) begin
            carry <= 0;
        end

        if (carry == 1) begin
            tens <= tens + 1;
            if (tens == 5) begin
                tens <= 0;
                hundreds <= 1;
                carry <= 1;
            end else if (tens > 5) begin
                tens <= 0;
                hundreds <= 0;
                carry <= 1;
            end
        end

        if (carry == 1) begin
            ones <= ones + 1;
            if (ones == 5) begin
                ones <= 0;
                carry <= 1;
            end
        end

        if (counter == 1) begin
            if (carry == 1) begin
                enable_threes <= 0;
                enable_twos <= 0;
                enable_ones <= 1;
            end else if (carry == 0) begin
                enable_threes <= 1;
                enable_twos <= 0;
                enable_ones <= 0;
            end
        end
        if (counter == 2) begin
            if (carry == 1) begin
                enable_threes <= 1;
                enable_twos <= 0;
                enable_ones <= 0;
            end else if (carry == 0) begin
                enable_threes <= 0;
                enable_twos <= 1;
                enable_ones <= 0;
            end
        end

        if (counter == 3) begin
            if (carry == 1) begin
                enable_threes <= 0;
                enable_twos <= 0;
                enable_ones <= 0;
            end else if (carry == 0) begin
                enable_threes <= 1;
                enable_twos <= 1;
                enable_ones <= 0;
            end
        end

        if (counter == 4) begin
            if (carry == 1) begin
                enable_threes <= 1;
                enable_twos <= 1;
                enable_ones <= 1;
            end else if (carry == 0) begin
                enable_threes <= 0;
                enable_twos <= 0;
                enable_ones <= 0;
            end
        end
    end

    assign ena = {enable_threes, enable_twos, enable_ones};
    assign q = {thousands, hundreds, tens, ones};

endmodule

