module TopModule(
    input  clk,
    input  ar,
    input  d,
    output q
);

    reg  [1:0] q_next;
    reg  [1:0] q;
    wire  reset;

    // Create an asynchronous reset from the input 'ar' and set it high to enable the reset
    assign reset = ~ar;

    // Create a positive edge triggered D flip flop
    always_pos_edge @(posedge clk) begin
        if (reset) begin
            q <= 2'b00;
        end else begin
            q <= q_next;
        end
    end

    // Update the next state of the D flip flop
    always @(posedge ar) begin
        q_next <= q;
    end

    // Update the state of the D flip flop with the input 'd'
    always @(posedge clk) begin
        if (reset) begin
            q <= 2'b00;
        end else begin
            if (d == 1) begin
                q <= 2'b01;
            end else if (d == 0) begin
                q <= 2'b00;
            end
        end
    end

endmodule

