module TopModule(
    input clk,
    input areset,
    input [7:0] d,
    output [7:0] q
);

    // Array of 8 D flip-flops
    reg [7:0] [3:0] dffs[7:0];

    // Reset all D flip-flops when areset is asserted
    always @(posedge areset or negedge clk) begin
        for (int i = 0; i < 8; i++) begin
            dffs[i][3] <= 4'b0000; // Reset all dffs to 0
        end
    end

    // Trigger each DFF based on the positive edge of clk
    always @(posedge clk) begin
        for (int i = 0; i < 8; i++) begin
            if (dffs[i][3] == 4'b0000) begin
                dffs[i][3] <= d[i]; // Set the dff based on the input d
            end
        end
    end

    // Output the result of the D flip-flops
    assign q = {dffs[0][3], dffs[1][3], dffs[2][3], dffs[3][3], dffs[4][3], dffs[5][3], dffs[6][3], dffs[7][3]};

