module TopModule (
    input wire in,
    input wire state,
    output reg next_state,
    output reg out
);

    // Define the state variables
    state_t cur_state, next_state;

    // Assign the initial state
    always @(posedge clk or posedge reset_n) begin
        if (~reset_n) begin
            cur_state <= A;
        end else if (next_state_valid) begin
            cur_state <= next_state;
        end
    end

    // Transition logic based on the state transition table
    always @(cur_state or in or state) begin
        case ({cur_state, in})
            {A, 0}: begin
                next_state <= A;
                out <= 0;
            end
            {A, 1}: begin
                next_state <= B;
                out <= 0;
            end
            {B, 0}: begin
                next_state <= C;
                out <= 0;
            end
            {B, 1}: begin
                next_state <= B;
                out <= 0;
            end
            {C, 0}: begin
                next_state <= A;
                out <= 0;
            end
            {C, 1}: begin
                next_state <= D;
                out <= 0;
            end
            {D, 0}: begin
                next_state <= C;
                out <= 0;
            end
            {D, 1}: begin
                next_state <= B;
                out <= 1;
            end
            default: begin
                next_state <= A;
                out <= 0;
            end
        endcase
    end

    // Assignment of next_state_valid to true when the state is valid
    assign next_state_valid = cur_state != A;

    // Instantiate the interface
    TopModuleInterface uut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

endmodule

