reg Qold;

always @(posedge clk) begin
    // Update Q based on the JK flip-flop truth table
    if ((j == 0) && (k == 0)) begin
        Q = Qold;
    end else if ((j == 0) && (k == 1)) begin
        Q = 0;
    end else if ((j == 1) && (k == 0)) begin
        Q = 1;
    end else if ((j == 1) && (k == 1)) begin
        Q = ~Qold;
    end
end

// Update Qold for next cycle
always @(posedge clk) begin
    Qold <= Q;
end

endmodule

