module TopModule(
    input  in,
    input  state   [3:0],  // One-hot encoded states
    output next_state [3:0],  // One-hot encoded next states
    output out
);

    // Initialize next_state as the current state
    assign next_state = state;

    // State transition table
    always_comb begin
        case (in)
            0 => begin
                // A -> A, B
                if (~state[0]) next_state[0] = 1;
                if (~state[1]) next_state[1] = 1;
                // B -> C, B
                if (state[0]) next_state[2] = 1;
                if (state[1]) next_state[1] = 1;
                // C -> A, D
                if (state[2]) next_state[0] = 1;
                if (~state[3]) next_state[3] = 1;
                // D -> C, B
                if (~state[2]) next_state[2] = 1;
                if (state[1]) next_state[1] = 1;
            end
            1 => begin
                // A -> C
                if (~state[0]) next_state[2] = 1;
                // B -> B
                if (state[0]) next_state[0] = 1;
                if (state[1]) next_state[1] = 1;
                // C -> A
                if (state[2]) next_state[0] = 1;
                // D -> B
                if (~state[3]) next_state[1] = 1;
            end
        endcase
    end

    // Derive output logic from next state
    always_comb begin
        case (next_state)
            4'b0001 : out = 1;
            4'b0010 : out = 0;
            4'b0100 : out = 0;
            4'b1000 : out = 1;
        endcase
    end

endmodule

