    reg [15:0] d_q[8:0];  // 8 D flip-flops, D latch for upper byte

    always @(posedge clk) begin
        if (!resetn) begin
            q_old[16:0] <= 16'h0;
            q[16:0] <= 16'h0;
            d_q[8:0] <= 8'h0;
        end else begin
            for (int i = 0; i < 16; i++) begin
                if (i < 8) begin
                    q[i] <= d_q[i];
                    d_q[i] <= d[i*2 : i*2+1];
                end else begin
                    q[i] <= d_q[i-8];
                    d_q[i-8] <= d[i*2-8 : i*2-1];
                end
            end
        end
    end

    always @(*)
        q[7:0] <= q[7:0];
    always @(*)
        q[15:8] <= q[15:15];

    assign q[15:0] = q_old[15:0] | q[15:0];

endmodule

