    input resetn,
    input [1:0] byteena,
    input [15:0] d,
    output [15:0] q
);

    // Create 16 D flip-flops
    reg [15:0] dffs [0:15];

    // Implement the byte-enable logic
    always @(posedge clk or posedge resetn) begin
        if (resetn) begin
            // Reset all DFFs
            for (int i = 0; i < 16; i = i + 1) begin
                dffs[i] <= 16'b0;
            end
        end else begin
            // Update DFFs based on byte-enable
            for (int i = 0; i < 16; i = i + 1) begin
                if (byteena[1] && i < 8) begin
                    dffs[i] <= d[15:8];
                end else if (byteena[0] && i >= 8) begin
                    dffs[i] <= d[7:0];
                end else begin
                    dffs[i] <= dffs[i];
                end
            end
        end
    end

    // Output the result
    assign q = dffs;

endmodule

