module TopModule(
    input a, input b, input c, input d,
    output out
);

// Define a separate module for the Karnaugh map logic
module karnaugh_map(
    input a, input b,
    input c, input d,
    output output
);

    // Use a 2-bit output to represent the output of the Karnaugh map
    logic output_00, output_01, output_11, output_10;

    // Calculate the output of the Karnaugh map
    assign output_00 = (a & b & ~c & ~d) | (~c & ~d & ~a & b);
    assign output_01 = (a & b & c & ~d) | (~a & b & ~c & ~d);
    assign output_11 = (a & ~b & c & d) | (~a & b & c & ~d);
    assign output_10 = (a & ~b & ~c & d) | (~a & ~b & c & ~d);

    // Use a combinational logic to select the output of the Karnaugh map
    logic [2:0] karnaugh_map_output;
    assign karnaugh_map_output = (a & b) ? 01 : ((a & d) ? 00 : ((c & d) ? 11 : 10));
    assign output = (karnaugh_map_output == 00) ? output_00 : (karnaugh_map_output == 01) ? output_01 : (karnaugh_map_output == 11) ? output_11 : output_10;

endmodule

// Instantiate the Karnaugh map module
TopModule karnaugh (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .out(karnaugh_map::output)
);

