module TopModule(
    input clk,
    input reset,
    output ena[3:0],
    output [15:0] q
);

    reg [15:0] q_next = 0;
    reg [3:0] ena_prev = 0;
    reg [3:0] tens_ena_prev = 0;
    reg [3:0] ones_ena_prev = 0;

    always @(posedge clk or negedge reset) begin
        if (reset) begin
            q_next = 0;
            tens_ena_prev = 0;
            ones_ena_prev = 0;
        end else begin
            // Increment the ones place
            q_next[0] = q_next[0] + 1;

            // If the ones place overflows, carry to the tens place
            if (q_next[0] == 4) begin
                q_next[0] = 0;
                q_next[1] = q_next[1] + 1;
            end

            // If the tens place overflows, carry to the hundreds place
            if (q_next[1] == 4) begin
                q_next[1] = 0;
                q_next[2] = q_next[2] + 1;
            end

            // If the hundreds place overflows, carry to the thousands place
            if (q_next[2] == 4) begin
                q_next[2] = 0;
                q_next[3] = q_next[3] + 1;
            end

            // Update enable signals
            if (q_next[1] == 1 && q_next[2] == 0 && q_next[3] == 0) begin
                tens_ena_prev = tens_ena_prev | {1, 0, 0};
            end else if (q_next[2] == 1 && q_next[3] == 0) begin
                tens_ena_prev = tens_ena_prev | {0, 1, 0};
            end else if (q_next[3] == 1) begin
                tens_ena_prev = tens_ena_prev | {0, 0, 1};
            end else begin
                tens_ena_prev = 0;
                ones_ena_prev = 0;
            end

            if (q_next[2] == 1 && q_next[3] == 0) begin
                ones_ena_prev = ones_ena_prev | {0, 0, 1};
            end else if (q_next[3] == 1) begin
                ones_ena_prev = ones_ena_prev | {0, 0, 1};
            end else begin
                tens_ena_prev = 0;
            end

            q_next = q_next;

            ena[0] = (q_next[1] == 1 && q_next[2] == 0 && q_next[3] == 0);
            ena[1] = (q_next[2] == 1 && q_next[3] == 0);
            ena[2] = (q_next[3] == 1);
            ena[3] = ones_ena_prev;
        end
    end

    assign q = q_next;

    always @(posedge clk) begin
        ena <= ena;
        tens_ena_prev <= tens_ena_prev;
        ones_ena_prev <= ones_ena_prev;
    end

    assign reset_q = reset ? 0 : q;

    always @(posedge reset) begin
        q <= reset_q;
    end

endmodule

