module TopModule(
    input clk,
    input reset,
    output [2:0] ena,
    output [15:0] q
);
    reg [2:0] ena_count = 3'b000; // initial value of enable count
    reg [15:0] q_count = 16'h0000; // initial value of BCD count
    reg [15:0] prev_q = 16'h0000; // previous value of BCD count

    always @(posedge clk or negedge reset) begin
        if (reset) begin
            q_count <= 16'h0000;
            ena_count <= 3'b000;
        end else begin
            if (~ena_count) begin // if the top bit is not asserted
                prev_q <= q_count;
            end

            if (~q_count) begin // if the most significant bit is not asserted
                q_count <= {q_count[3:1], q_count[15:14] + 1};
            end else if (~q_count[2]) begin // if the tens bit is not asserted
                prev_q[7:4] <= prev_q[15:12] + 1;
                q_count[15:14] <= 0;
            end else if (~q_count[1]) begin // if the hundreds bit is not asserted
                prev_q[8:7] <= prev_q[15:14] + 1;
                q_count[15:14] <= 0;
                prev_q[7:4] <= 0;
            end else if (~q_count[0]) begin // if the thousands bit is not asserted
                q_count[9:8] <= q_count[15:14] + 1;
                q_count[15:14] <= 0;
                prev_q[8:7] <= 0;
                prev_q[7:4] <= 0;
            end
            else if (q_count[0]) begin
                q_count[0:0] <= 0;
            end
            else if (q_count[1]) begin
                q_count[1:0] <= 0;
                prev_q[8:7] <= 0;
                q_count[8:7] <= q_count[15:14] + 1;
                q_count[15:14] <= 0;
            end
            else if (q_count[2]) begin
                q_count[2:1] <= 0;
                prev_q[9:8] <= q_count[15:14] + 1;
                q_count[15:14] <= 0;
            end
            else if (q_count[3]) begin
                q_count[3:2] <= 0;
                prev_q[10:9] <= q_count[15:14] + 1;
                q_count[15:14] <= 0;
            end
            else if (q_count >= 1000) begin
                q_count <= 0;
                prev_q[10:0] <= 0;
            end
            else if (q_count[3] || q_count[2] || q_count[1]) begin
                prev_q <= q_count;
            end
        end
        q <= q_count; // update output for this clock cycle
        ena <= ena_count;
        ena_count <= (ena_count + 1) & 3'b111;
    end
endmodule

