module TopModule(clk, w, R, E, L, Q);

    reg [2:0] prev_state;
    reg [2:0] curr_state;
    reg [7:0] value;
    reg Q;

    initial Q = 0;

    always @(posedge clk) begin
        if (w) begin
            curr_state = 0;
            value = w;
            Q = w;
        end
        else if (R) begin
            curr_state = R;
            value = R;
            Q = value;
        end
        else if (E && L && prev_state == 0) begin
            curr_state = 0;
            value = prev_state;
            Q = value;
        end
        else if (E && L && prev_state != 0) begin
            curr_state = prev_state;
            value = prev_state;
            Q = value;
        end
    end

    assign Q = value[0];

endmodule

