module TopModule(
    input  in,
    input  [3:0] state,
    output  [3:0] next_state,
    output  out
);

    // State encoding
    reg [3:0] currentState = state;
    reg [3:0] nextStateState;

    // State transition logic
    assign nextStateState = case(state)
        4'b0001 : currentState == 4'b0001 ? 4'b0001 : 4'b0010;
