    parameter A = 4'b0001,
               B = 4'b0010,
               C = 4'b0100,
               D = 4'b1000;

    // Define the state transition table
    always @(posedge in) begin
        // State transition based on the current state and the input
        case (state)
            A: next_state = B;
            B: next_state = C;
            C: next_state = A;
            D: next_state = C;
            default: next_state = state; // Stay in the same state if input is 0
        endcase

        // Output logic
        out = state; // Always output the current state
    end

