module TopModule(
    input  [255:0] in,
    output [7:0] out
);

    reg [8:0] onebits[8:0];
    reg [8:0] partial_sums[8:0];
    reg [8:0] total_sum;

    always_comb begin
        // Initialize partial sums and total sum
        partial_sums[0] = 0;
        total_sum = 0;

        // Iterate over each bit in the input vector
        for (int i = 0; i < 8; i++) begin
            // Calculate the partial sum for the current bit
            partial_sums[i] = partial_sums[i - 1] + in[i];

            // Calculate the one bits for the current bit
            if (in[i] == 1) begin
                for (int j = i + 1; j < 8; j++) begin
                    onebits[j] = 1;
                end
            end
            if (i < 7 && in[i + 1] == 1) begin
                onebits[i + 1] = 1;
            end
        end

        // Calculate the total sum
        for (int i = 0; i < 8; i++) begin
            total_sum = total_sum + partial_sums[i] * onebits[i];
        end

        // Calculate the population count output
        out = total_sum;
    end

endmodule

