    if (~resetn) begin
      q_ <= '0;
    end else begin
      if (byteena == 2'b01) begin
        q_[WIDTH:1] <= d[15:8];
      end else if (byteena == 2'b10) begin
        q_[WIDTH:1] <= d[7:0];
      end else begin
        q_[WIDTH:1] <= '0;
      end
      for (int i = WIDTH-1; i >= 0; i--) begin
        if (byteena == 2'b01) begin
          q_[i] <= (q_[i+1] & ~d[i]);
        end else if (byteena == 2'b10) begin
          q_[i] <= (q_[i+1] | d[i]);
        end else begin
          q_[i] <= q_[i+1];
        end
      end
    end
  end

  assign q = q_[0:WIDTH-1];

endmodule

