module TopModule(
    input clk,
    input reset,
    output reg [2:0] ena,
    output reg [15:0] q
);

reg [15:0] q_prev;
reg [3:0] tens, ones;

always @(posedge clk) begin
    if (reset) begin
        q <= 0;
        tens <= 0;
        ones <= 0;
        ena <= 0;
    end else begin
        q <= q_prev;
        tens <= tens + (ones == 4'b0000 ? 1'b0 : 1'b1);
        ones <= ones + 1;
        if (ones >= 4'b0001) begin
            ones <= 4'b0000;
            tens <= tens + 1;
            if (tens == 4'b0100) begin
                tens <= 4'b0000;
                ena <= ena + 1;
            end else if (tens == 4'b0110) begin
                tens <= 4'b0100;
                ena <= ena + 1;
            end
        end
    end
end

initial begin
    q_prev <= 16'b0000000000000000;
end

assign q[7:4] = tens;
assign q[3:0] = ones;
assign ena = ena;

endmodule

