module TopModule(
    input clk,
    input a,
    input b,
    output out_assign,
    output out_always_comb,
    output out_always_ff
);

    // XOR gate using assign statement
    assign out_assign = ~((a ^ b) & ~(a | b));

    // XOR gate using combinational always block
    reg out_always_comb;
    always_comb begin
        out_always_comb = ~(a ^ b);
    end : always_comb
    assign out_always_comb = out_always_comb;

    // XOR gate using clocked always block with flip-flop
    reg out_always_ff;
    reg [1:0] state;
    always @(posedge clk) begin
        if (state == 00) begin
            state <= 01;
            out_always_ff <= ~(a ^ b);
        end else if (state == 01) begin
            state <= 00;
            out_always_ff <= ~(a ^ b);
        end else if (state == 10) begin
            state <= 11;
            out_always_ff <= a;
        end else if (state == 11) begin
            state <= 10;
            out_always_ff <= b;
        end
    end : always
    assign out_always_ff = out_always_ff;

endmodule

