module TopModule(
    input clk,
    input reset,
    output [3:0] q
);

    reg [3:0] count;
    reg [1:0] carry;

    always_comb begin
        if(reset) begin
            count = 0;
            carry = 0;
        end else begin
            if(clk == 0) begin
                carry = 0;
            end else if(count == 15) begin
                carry = 1;
                count = 0;
            else begin
                carry = 1;
            end
        end
    end

    always_comb begin
        q = (carry & 2) ? 4'd2 : (carry & 1) ? 4'd1 : (count == 0) ? 4'd0 : 4'd count + 4'd 4;
    end

endmodule

