module PopCount (
    input  [255:0] in,
    output [7:0]  out
);

    reg [7:0] count;

    // Count the number of '1's in the input vector
    always @(posedge in or negedge in)
    if (in != 0) begin
        count = count + 1;
    end else if (count != 0) begin
        count = count - 1;
    end

    // Assign the count to the out port
    assign out = count;

endmodule

